window.DX_CHAPTERS = [{"id": "reasoning", "title": "Clinical reasoning & evidence-based assessment", "week": "Week 1", "modules": ["m01", "m02", "m03"], "summary": "Build a defensible clinical argument, use the four integrity features, and select tools for the question.", "source": "Week 1 slides 4–13; assigned ASHA TLR modules; September 9/11 lectures", "stages": [["Start with the question", "Assessment is a clinical argument. Week one puts clinical reasoning at the center: gather information from several sources, interpret it critically, and decide what the evidence supports. The seven-stage framework begins with referral and review. History and interview come next, then observation, assessment, analysis, diagnosis and recommendations, and the report and results conference. A test score is evidence within that process. It cannot replace the process.", ["Referral → history → observation", "Assessment → analysis", "Diagnosis → report & conference"]], ["The four integrity features", "The slide you flagged for Test One names four features. Be thorough. Use a variety of assessment methods. Use evidence-based approaches. Tailor the assessment to the individual. Keep their explanations paired correctly: valid and reliable methods belong to evidence based; age, skill level and ethnocultural background belong to individual tailoring.", ["Thorough", "Varied methods", "Evidence based", "Tailored to the client"]], ["Three components; four steps", "Evidence-based practice integrates research and client data, clinical expertise, and the client or caregiver perspective. Internal evidence comes from your client; external evidence comes from scientific research. The four steps are frame the question, gather evidence, assess the evidence, and make the clinical decision. Assessment must also remain within your professional competence.", ["Evidence · internal + external", "Clinical expertise", "Client perspectives", "Frame → gather → assess → decide"]], ["Match the tool to its purpose", "The assigned videos extend this reasoning to test selection. Check purpose, diagnostic accuracy, normative representation, relevant skills, reliability, and sufficiency. A screening instrument does not become a diagnostic instrument because it is convenient. Sensitivity and specificity apply to the particular target disorder studied. If a test score conflicts with everyday communication, gather converging evidence and document the limits.", ["Purpose → accuracy → representation", "Relevant skill → consistency", "Sufficiency → converging evidence"]]]}, {"id": "scores", "title": "Standardized testing, scores & psychometrics", "week": "Week 2", "modules": ["m05", "m06", "m07", "m08", "m18"], "summary": "Administer from the manual, work the numbers, and distinguish validity, reliability, sensitivity and specificity.", "source": "Week 2 slides 5–24; PPVT assessment activity; relevant textbook Chapter 1", "stages": [["Preserve the comparison", "Read the manual before administering a standardized test. Confirm purpose, population, psychometrics, and procedures. An accommodation changes access while preserving the construct and permitted administration. Extra cues forbidden by the manual, translated items, or altered response requirements can be modifications; the original standard score may no longer be comparable. Norm referenced means comparison with peers. Criterion referenced means comparison with an expected performance level.", ["Manual first", "Accommodation: access preserved", "Modification: comparison may change"]], ["Age, basal and raw score", "Chronological age selects the correct age norms. Adjusted age subtracts prematurity for the developmental comparison specified by the source. A basal establishes credit for easier items; a ceiling stops testing as harder items are likely to be missed. Their exact rules belong to the particular manual. The raw score is the points earned under those rules. An incorrect age or raw score can contaminate every derived score.", ["Correct age → correct norms", "Basal: easier-item credit", "Ceiling: stopping rule", "Raw score → derived scores"]], ["Keep the score scales distinct", "The course table gives standard scores a mean of one hundred and standard deviation fifteen. Scaled scores use ten and three. A z score uses zero and one. Stanines use five and two. Standard score one hundred fifteen and scaled score thirteen are both one standard deviation above their means. Percentile rank describes the norm group at or below the score. It is not percent correct. An age equivalent is descriptive, not an eligibility or severity rule.", ["Standard 100 / 15", "Scaled 10 / 3", "z 0 / 1 · stanine 5 / 2", "Percentile ≠ percent correct"]], ["Trust requires several properties", "A wider confidence interval accompanies a higher confidence level; it expresses measurement uncertainty. It does not repair a poor test. Validity asks whether the intended construct is measured. Reliability asks whether results are consistent. Standardization asks whether procedures are uniform. Freedom from bias asks about fairness. Sensitivity detects a disorder among people who have it. Specificity correctly clears people who do not. Use the stated convention for boundary scores and age borrowing.", ["Validity · intended construct", "Reliability · consistency", "Sensitivity · disorder present", "Specificity · disorder absent"]]]}, {"id": "culture", "title": "Cultural & linguistic assessment", "week": "Week 3", "modules": ["m04"], "summary": "Interpret performance within the client’s linguistic systems and use dynamic evidence without false norm comparisons.", "source": "Week 3 multicultural slides 2–16; September 14 lecture; textbook Chapter 3", "stages": [["Difference or disorder", "The primary assessment decision is difference or disorder. A pattern unlike Mainstream American English is not automatically a disorder. Learn the communication expectations of the client’s community, languages and dialects. Limited eye contact, for example, may reflect a cultural expectation. Interpret the observation before assigning a clinical label.", ["Pattern → linguistic context", "Expected difference", "Unexplained difficulty → investigate"]], ["ASKED is an ongoing process", "The cultural competence model is ASKED: awareness, skill, knowledge, encounters and desire. Competence requires continuing self-assessment. A language history asks which languages are used, how frequently, where and with whom. Assess abilities in both languages, one language at a time, with appropriate assistance when needed. Family, teachers and interpreters contribute information that a single English test cannot supply.", ["Awareness · Skill · Knowledge", "Encounters · Desire", "History in both languages"]], ["Teach, then examine learning", "Dynamic assessment compares an independent attempt with performance after instruction and support. Observe what cues help, how much support is needed, and whether learning transfers. Improvement can support an experience-based explanation. Limited improvement raises concern, but the whole profile still matters. Dynamic evidence is not simply a second administration of an unchanged test.", ["Independent attempt", "Instruction + support", "Retest with less help", "Observe transfer"]], ["Use interpreters deliberately", "Brief the interpreter on the purpose and tasks, work together during the assessment, and debrief afterward. Speak to the client and check understanding. Translating an English standardized test does not create validated norms for another language. Modified tasks can provide useful descriptive information; identify those limits in the report instead of presenting an invalid normative comparison.", ["Brief", "Interact", "Debrief", "Modified score: disclose limits"]]]}, {"id": "evaluation", "title": "Complete evaluation, interview & reporting", "week": "Week 3–4", "modules": ["m09", "m10", "m11"], "summary": "Connect history, direct evidence and functional impact; interview without leading; report a defensible synthesis.", "source": "Week 3 overview slides 2–20; Week 4 interview materials; September 9–14 lectures", "stages": [["Build a complete evaluation", "A complete evaluation combines history, interview, direct assessment, analysis, report and results sharing. Hearing screening or recent audiological findings help address hearing as a contributor. The setting changes the immediate question: school evaluation examines educational impact; an outpatient evaluation considers functional outcomes; acute care may prioritize a targeted time-sensitive assessment.", ["History + interview", "Direct assessment + hearing", "Analyze → report → share"]], ["Start broad, then clarify", "Open the interview with rapport, purpose and structure. Ask open-ended questions about the main concern, onset, change, consistency and everyday impact. Follow with specific examples and relevant developmental, medical, hearing and language history. Listen actively and clarify contradictions. A family’s priorities help shape the evaluation. A history is a starting point, and informant reports still need interpretation.", ["Opening → body → closing", "Open question → specific follow-up", "Concern + onset + impact"]], ["Integrate before diagnosing", "Consider findings in the context of the history. A normal vocabulary score can coexist with difficulty conversing with peers. A low timed score can coexist with effective compensatory communication. Do not force a diagnosis from conflicting evidence. Further testing can accompany a diagnosis and plan. Recommendations specify goals, setting, frequency and session duration, based on the supported needs.", ["Score + sample + observations", "History + functional impact", "Synthesis → recommendations"]], ["Report the clinical meaning", "A useful report includes identifying information, referral reason, history, procedures, results by domain, clinical impressions and recommendations. Explain quantitative findings and qualitative function. In the conference, use clear language, recognize strengths, allow time for questions, and close with next steps. Protect identifying health information when sharing records. A list of scores without functional interpretation is an unfinished clinical argument.", ["Results + functional meaning", "Clear language + strengths", "Questions → next steps"]]]}, {"id": "oral", "title": "Oral mechanism, movement & DDK", "week": "Week 4 & Week 6", "modules": ["m12", "m13", "m14"], "summary": "Connect structures to function, interpret patterns, and understand why each oral task is administered.", "source": "Week 4 common procedures slides 2–7; assigned OPE video; Boot Camp figures; Week 6 slide 26; Form 6–1 pp.169–172", "stages": [["Structure and function", "The oral mechanism examination asks whether structure or function contributes to communication. Observe posture and natural rest before giving commands. Then compare movement, symmetry, range, coordination and endurance. Standard precautions apply across settings. Gloves, adequate lighting and appropriate examination tools support clear observation. Record what you see and how it affects the task.", ["Natural rest → movement", "Structure + functional impact", "Standard precautions"]], ["Choose tasks by purpose", "Pucker and smile examine lip range and symmetry. Puffing and holding cheek air probes lip closure and pressure, with attention to nasal emission. Tongue movements examine excursion, range, symmetry and strength. Sustaining ah allows observation of velar movement and the uvula, alongside nasality. The point of Form six dash one is to understand why the task is used, not recite commands without a purpose.", ["Pucker / smile → lip range", "Puff / hold → seal & pressure", "Tongue tasks → range / strength", "Sustained ah → velar movement"]], ["Interpret the pattern", "Stability supports a position. Mobility moves through range. Dissociation moves one part independently. Grading controls speed, force and range. A jaw moving during a tongue task may be compensation rather than independent tongue control. The assigned video distinguishes horizontal overjet from vertical overbite. Its submucous cleft warning combines a bifid uvula, translucent midline zone and posterior hard-palate notch. One sign alone does not establish the diagnosis.", ["Stability · Mobility", "Dissociation · Grading", "One sign ≠ diagnosis"]], ["DDK gives more than speed", "Alternating motion rate repeats one syllable; sequential motion rate changes syllables, such as puh tuh kuh. Observe accuracy, rhythm, consistency and coordination as well as rate. Adequate single-syllable repetitions with difficulty sequencing raises a motor-planning question; it is not a stand-alone CAS diagnosis. Relate each observation to speech, resonance, feeding or airway function and the need for additional assessment.", ["AMR: one syllable", "SMR: changing syllables", "Rate + accuracy + rhythm", "Observation → interpretation"]]]}, {"id": "sampling", "title": "Speech sampling, rate & intelligibility", "week": "Week 4", "modules": ["m15"], "summary": "Obtain a representative sample, calculate rate and intelligibility, and interpret the communication context.", "source": "Week 4 slides 6–15; relevant textbook Chapter 6; Week 6 slide 12", "stages": [["Administer DDK consistently", "For the course’s more common DDK method, measure the seconds needed for a specified number of repetitions. Instruct and model, say go and start timing, then stop after twenty repetitions of a single syllable. After examining syllables separately, time ten repetitions of puh tuh kuh. Record the conditions and findings. The alternate method counts syllables produced within a fixed time.", ["Model → go → time", "20 single-syllable repetitions", "10 puh-tuh-kuh repetitions"]], ["Make the sample representative", "The current Week four slide specifies fifty to one hundred minimum utterances. Build rapport, minimize interruptions, wait, and use topics that elicit more than names or yes-no answers. Vary activities, contexts and partners when possible. Pictures with actions, personal events and narrative retelling provide connected language. Reading supplies fixed words that cannot be avoided, but is appropriate only for a client who can read the material.", ["50–100 minimum utterances", "Wait · vary context", "Conversation + narratives"]], ["Work the rate", "Record at least one to two minutes of connected speech for the course rate procedure. Time the sample in seconds, count its words, divide words by seconds and multiply by sixty. Sixty words in seventy-five seconds gives forty-eight words per minute. The clinical question is how rate affects this person’s communication. A norm alone cannot describe that effect.", ["Words ÷ seconds × 60", "60 ÷ 75 × 60 = 48 wpm", "Interpret communicative effect"]], ["Intelligibility depends on context", "Intelligibility is how well a listener understands speech. Error type and frequency matter, but so do listener familiarity, context, face-to-face contact, nonverbal cues and environment. Transcribe a representative sample and calculate words understood divided by total words, times one hundred. Record the conditions. Eighty understood words out of one hundred is eighty percent intelligibility, not an articulation percentile rank.", ["Understood ÷ total × 100", "80 / 100 = 80%", "Report listener + context"]]]}, {"id": "informal", "title": "Observation, dynamic assessment, play & narratives", "week": "Week 5", "modules": ["m16", "m17"], "summary": "Distinguish what you observe, what a task elicits and what teaching changes; analyze language and play evidence.", "source": "Week 5 slides 2–17; September 23 lecture; supplied play/cause-and-effect activities", "stages": [["Three methods, three questions", "Clinical observation watches and listens: what is the client doing? Informal assessment sets up a non-standardized task: what can the client do on this task? Dynamic assessment teaches and examines the response: what changes with support, and can learning be used again? You can observe communication during a standardized assessment. The setting alone does not decide which method the observation represents.", ["Observe: see / hear", "Informal: set a task", "Dynamic: teach + retest"]], ["Compare support and transfer", "Begin with an independent attempt. Teach using models, cues, feedback and practice. Retest with reduced support or a new task. The narrative example teaches character, setting, problem, action and outcome, then examines a new story. Repeating a language sample without instruction is not dynamic assessment. Keep the amount of help and the transfer evidence visible.", ["Test → teach → retest", "Reduce support", "New story → transfer"]], ["Language and narrative levels", "Language sample analysis examines form, semantic intent, use, rate and sequencing across representative contexts. Semantic analysis looks at vocabulary variety, unusual substitutions, empty words and word finding. Establish story comprehension before interpreting retelling. Macrostructure is the story’s organization. Microstructure is grammar, vocabulary, syntax and cohesion. Higher-level language includes inference, motivation, causality and perspective.", ["Macro: story organization", "Micro: language within story", "Higher level: inferred meaning"]], ["Observe play without overclaiming", "The class activities examine cause and effect, intention and play. Watch whether an action is repeated to obtain an outcome, how the child communicates a purpose, and whether symbolic play appears. Motor, sensory and access barriers can limit task performance. One unsuccessful toy interaction cannot establish absent understanding. Use the particular supplied checklist in its own context; do not merge its developmental ages with unrelated speech-sound norms.", ["Action → outcome → repetition", "Intention + symbolic play", "Access barriers → interpretation"]]]}, {"id": "ssd", "title": "Comprehensive SSD assessment & GFTA recording", "week": "Week 6", "modules": ["m20"], "summary": "Combine speech contexts, history, oral/hearing evidence, stimulability and impact; practice accurate error recording.", "source": "Week 6 slides 2–16,21–26; September 30 lecture; textbook Chapter 7 selected sections", "stages": [["Screening is the first question", "A speech sound screening quickly identifies people who may need further assessment. It is not an in-depth evaluation or a diagnosis. A comprehensive assessment considers relevant history, oral structure and function, hearing, perception, single words and connected speech. Speech sound difficulty may involve perception, planning, articulation or phonology. Match evidence to the suspected mechanism.", ["Screen: identify possible concern", "Evaluate: converging evidence", "History + hearing + oral + speech"]], ["Compare word and connected speech", "Single-word tests often sample a sound in only one context and may omit vowels or linguistic varieties. Connected speech adds error consistency, patterns, rate and intelligibility. Analyze the number, type, form and position of errors. Stimulability asks whether the client can produce an erred sound correctly with assistance; it provides prognostic information. It does not automatically erase a disorder.", ["Single word + connected speech", "Errors: type / position / consistency", "Stimulability → prognosis"]], ["Norms are one part of diagnosis", "Developmental sound acquisition, conversational acquisition, consonant-cluster development and occurrence frequency answer different questions. Use the relevant table and context. Do not diagnose from developmental norms alone. Consider intelligibility, stimulability, perception, error patterns, social and academic impact, history and language. Phonological processing concerns thinking about, remembering or manipulating sounds; speech sound production concerns how the words are spoken.", ["Acquisition ≠ frequency", "Processing ≠ production", "Norms + function + context"]], ["Record the production you hear", "The Week six GFTA activity requires real-time error recording. Use IPA for substitutions, a dash for an omission, diacritics or notes for a distortion, and N R for no response. Follow the appropriate test manual’s prompts and scoring. No response is not automatically an omitted phoneme. GFTA findings contribute to a broader profile alongside connected speech, hearing and oral examination, history and other relevant measures.", ["Substitution → IPA", "Omission → dash", "Distortion → diacritic / note", "No response → NR"]]]}, {"id": "cas", "title": "Functional SSD versus childhood apraxia", "week": "Week 6", "modules": ["m19"], "summary": "The accepted chapter: repeated productions, transitions, stress and the whole profile.", "source": "Week 6 slides 1,4,17–20; September 30 lecture; textbook pp.225–227", "stages": []}];
window.DX_COURSE_GUIDE = [{"id": "m01", "number": 1, "title": "Assessment is a clinical argument", "kicker": "Week 1 · Framework", "week": "Week 1 (+ lectures 9/9, 9/11)", "summary": "What an assessment is for, the seven-stage process on her Week 1 slide, and what to do when your data disagree.", "sections": [{"h": "The one sentence she built the course on", "body": ["Her Week 1 'Why and How' slide names the single most important thing to learn: **clinical reasoning**, the ability to gather information from multiple sources, interpret it critically, and make informed decisions about a person's communication abilities. The slide adds: assessment is not simply administering tests; it is using evidence to answer a clinical question.", "The slide then lists what a clinician who 'thinks like a clinician' can do: ask the right questions, select appropriate methods, integrate information from interviews, observations, records and testing, recognize limitations of the data, and develop evidence-based recommendations. A student who memorizes test names but cannot interpret findings 'will struggle as a clinician.'"], "callouts": [{"k": "source", "t": "4756 WEEK 1 slides 4-5. Slide 5 restates it: assessment is a comprehensive process of collecting information and using clinical reasoning to make informed decisions.", "ev": "slide"}, {"k": "trap", "t": "Watch for statements that shrink assessment to 'giving a test' or 'getting a score'. On her slides those are the wrong half of a contrast.", "ev": "inference"}], "src": ["W1:slides 4-5"]}, {"h": "The seven-stage process (Week 1, slide 6)", "visual": "process", "table": {"head": ["#", "Stage", "What happens"], "rows": [["1", "Referral & Review", "Identify the reason for the evaluation; review records, reports, background."], ["2", "Case History & Interview", "Gather information from client, family, teachers or caregivers: concerns, development, medical history, daily functioning."], ["3", "Observation", "Observe communication in natural or structured settings: strengths and concerns."], ["4", "Assessment", "Administer formal and informal measures: standardized tests, language samples, dynamic assessment, oral mechanism exam."], ["5", "Analysis & Interpretation", "Integrate testing, observations, interviews and records to determine abilities and needs."], ["6", "Diagnosis & Recommendations", "Decide whether a disorder is present; develop evidence-based recommendations or referrals."], ["7", "Report & Results Conference", "Document findings in a professional report and communicate results to the client, family and/or team."]]}, "callouts": [{"k": "numbers", "t": "Seven stages. Observation is its own stage BEFORE formal/informal assessment on this slide. Analysis comes BEFORE diagnosis; the report and results conference come last.", "ev": "slide"}, {"k": "lecture", "t": "9/9 lecture: case history and interview 'are kind of occurring at the same time' in practice; sometimes history arrives before the visit through intake forms or chart review.", "ev": "lecture"}], "src": ["W1:slide 6", "L0909"]}, {"h": "When the data disagree", "body": ["She spent real class time on this (9/9 and 9/11). If a standardized test comes out in the normal range but your observations and informal measures show a problem, you have conflicting results. Her words: 'You always go with your clinical judgment.' She described pulling another test, and justifying therapy to insurance with the informal and observational results, which she called just as clinically relevant as the standardized score.", "On 9/11 she asked: when the standardized results and your clinical observations don't match, are you forced into making a diagnosis? 'No, you're not. Ethically, you say that... further testing is warranted.' She added that this may mean you did not prepare the assessment appropriately.", "She also said a formal measure supersedes informal ones in one situation: when a standardized score is required for qualification (eligibility)."], "callouts": [{"k": "gonsoulin", "t": "Historical pattern (COMD 4382 record): she tested 'a failed screen means disorder' and similar over-conclusions as FALSE. The current-course analog is 'one score settles it'. That is a documented style of item, not a prediction of a specific question.", "ev": "historical"}, {"k": "source", "t": "Lecture transcripts are auto-captioned and partly garbled. Only statements that are legible and repeated are used as answer evidence here.", "ev": "lecture"}], "src": ["L0909", "L0911", "W3A:slide 13"]}], "concepts": ["m1-reasoning", "m1-process", "m1-conflict"]}, {"id": "m02", "number": 2, "title": "Foundational integrity, EBP, ethics and HIPAA", "kicker": "Week 1 · Standards", "week": "Week 1", "summary": "The four features of a good assessment (the slide you flagged 'WILL BE ON TEST ONE'), the EBP triangle and four steps, ASHA's competence rule, HIPAA, and Week 1's cultural considerations.", "sections": [{"h": "Foundational Integrity (Week 1, slide 7)", "body": ["**A good assessment is:**"], "bullets": ["**Thorough**: as much relevant information as possible.", "**Uses a variety of assessment methods**: interview, case history, observations, and formal and informal testing measures.", "**Evidence based**: rely on valid and reliable assessment approaches.", "**Tailored to the individual client**: appropriate for the client's age, gender, skill levels and ethnocultural background."], "callouts": [{"k": "flag", "t": "Your Test One folder contains a screenshot of this slide saved as 'WILL BE ON TEST ONE'. That is your record of her emphasis; it does not say how it will be worded.", "ev": "flag"}, {"k": "trap", "t": "Each feature has a specific sub-bullet. Swap them and you get a classic sibling-swap item: e.g., 'Evidence based: appropriate for age, gender and ethnocultural background' pairs the wrong sub-bullet.", "ev": "inference"}], "src": ["W1:slide 7", "T1"]}, {"h": "Evidence-based practice (slides 8-10)", "visual": "ebp", "body": ["Slide 8 (an image of ASHA's EBP page) defines EBP as the integration of three components: **clinical expertise/expert opinion** (knowledge, judgment and critical reasoning from training and professional experience), **evidence, external and internal** (scientific literature = external; data and observations collected on your individual client = internal), and **client/patient/caregiver perspectives** (personal and cultural circumstances, values, priorities, expectations).", "Slide 9 gives ASHA's four steps: **1 Frame your clinical question → 2 Gather evidence → 3 Assess the evidence → 4 Make your clinical decision.**", "Slide 10 (Ethics): ASHA's Scope of Practice and Code of Ethics require that professionals only engage in assessment **within their competence**, based on education, training and experience. ASHA's position: EBP is a **core professional standard**; assessment must be informed by the best available evidence, the clinician's expertise, and the client's perspective."], "callouts": [{"k": "numbers", "t": "3 components, 4 steps. 'Internal evidence' = data from YOUR client. That word is an easy swap target.", "ev": "slide"}, {"k": "gonsoulin", "t": "COMD 4382 record: 'Which is NOT a component of EBP?' appeared on her practice exam (the joke distractor 'Tick-Tock advice from Dr. Syntax'). Historical, not a forecast.", "ev": "historical"}], "src": ["W1:slides 8-10", "CODEX:section 4 T1"]}, {"h": "HIPAA (slide 11 table)", "table": {"head": ["Topic", "On her slide"], "rows": [["Stands for", "Health Insurance Portability and Accountability Act of 1996"], ["Primary purpose", "Protects the privacy and security of individuals' health information"], ["PHI", "Medical records, diagnoses, treatment and insurance information, names, birth dates, other identifying health information"], ["Patient rights", "Access records, request corrections, learn how information is used and shared"], ["Who must follow", "Health care providers, health plans, health care clearinghouses, business associates"], ["Privacy Rule", "National standards for protecting health information and limiting unnecessary disclosures"], ["Security Rule", "Safeguards to protect ELECTRONIC protected health information (e-PHI)"], ["Compliance examples", "Secure storage; proper authorization before disclosure; discuss only with authorized individuals"]]}, "callouts": [{"k": "trap", "t": "Privacy Rule vs Security Rule is a sibling pair. The Security Rule is the one tied to electronic PHI.", "ev": "inference"}, {"k": "textbook", "t": "Textbook adds: school SLPs are generally not HIPAA-covered entities (FERPA provides similar protections), with exceptions; covered clinicians need an NPI and must give clients the privacy policy.", "ev": "textbook"}], "src": ["W1:slide 11", "TB1: relevant section reviewed for this topic"]}, {"h": "Cultural and linguistic considerations (slide 12)", "body": ["The guiding question on the slide: **'Is this individual's communication pattern a difference resulting from language or culture, or is it evidence of an underlying disorder?'**", "Linguistic factors: primary language at home and elsewhere; whether standardized tests are available for that population; whether an interpreter is needed. Example: a child omitting certain English grammatical markers may be showing dialect features, not a language disorder.", "Cultural influences: social rules in the client's community that may influence testing. Example: limited eye contact may reflect cultural norms rather than poor social communication skills."], "src": ["W1:slide 12"]}], "concepts": ["m2-integrity", "m2-ebp", "m2-ethics", "m2-hipaa", "m2-culture"]}, {"id": "m03", "number": 3, "title": "The two ASHA videos: evidence-based assessment", "kicker": "Week 1 · Flagged videos", "week": "Week 1 Friday", "summary": "Both ASHA TLR Hub modules linked on her Week 1 'Videos' slide, which you saved as 'WILL BE ON EXAM'. Built from the caption files in your Week 1 Friday folder.", "sections": [{"h": "Why these two videos matter", "body": ["Her Week 1 slide 13 ('Videos') links two ASHA TLR Hub modules: **Why We Need Evidence-Based Assessment** and **A Decision-Making Process for Selecting an Assessment Tool**. Your Test One folder holds a screenshot of that slide saved as 'WILL BE ON EXAM'. The caption files in your Week 1 Friday folder are the transcripts of those two modules (the speaker names and titles match), so this lab can teach them. The earlier lab marked the videos as missing.", "Captions are auto-generated. Names that came through garbled (the author of the 2021 decision-making process, the name of the bias procedure) are not used as answer keys."], "callouts": [{"k": "flag", "t": "Your flag labels are your record of her emphasis. They do not reveal question wording or weighting.", "ev": "flag"}], "src": ["W1:slide 13", "T1", "VA", "VB"]}, {"h": "Video 1: Why we need evidence-based assessment", "body": ["**Definition.** Evidence-based assessment is a clinical decision-making process for determining an assessment approach that integrates the best available evidence from **scientific research**, **clinical practice experience**, and **client preferences and characteristics** (built on the E3BP definition). EBP includes assessment AND treatment, but clinicians tend to apply EBP thinking to treatment only.", "**Four problems** the speaker identifies: (1) **80.6%** of surveyed SLPs reported using **informal discussion with colleagues** to determine an assessment approach; (2) only **57%** report using **psychometrics** (validity, reliability, sensitivity, specificity) when selecting a test, with **availability and familiarity** the top two factors in test selection; (3) a **poor understanding of diagnostic accuracy** research; (4) **bias** in assessment (limits of standardized testing, over- and underestimation of performance, disproportionality data).", "**Solutions:** update instructional practices (connect the purpose of the assessment, emphasize validity, understand psychometrics); implement **decision-making processes**; use a structured process to evaluate, understand and mitigate bias."], "table": {"head": ["Case", "First evaluation", "What was missed", "Second evaluation found", "Outcome"], "rows": [["3-year-old, primarily Spanish-speaking family, 2-word phrases", "Play-based, in Spanish; language samples; phonemic inventory. No hearing test (parents reported no hearing concerns); no oral mech exam (child ate well)", "Hearing screening and oral mechanism exam", "Failed hearing screen → audiology: moderate sensorineural hearing loss, hearing aids; motor coordination/sequencing issues on the oral mech exam", "A year of therapy with minimal progress; new plan (auditory-verbal + motor planning approaches) → progress almost immediately"], ["75-year-old man, severe demyelinating polyradiculoneuropathy, respiratory distress, ICU", "Bedside swallow evaluation: no issues; general diet and thin liquids; SLP signed off", "Chart review, interview, full oral mechanism exam, instrumental study", "Lingual fasciculations, mild dysarthria; videofluoroscopy showed aspiration of thin and mildly thick liquids", "Modified diet to reduce aspiration pneumonia risk"]]}, "callouts": [{"k": "numbers", "t": "80.6% informal discussion. 57% use psychometrics. Top two selection factors: availability and familiarity.", "ev": "video"}, {"k": "lecture", "t": "The same message runs through her slides: Week 3 lists a hearing screening as a core component 'because hearing loss can mimic or compound speech-language difficulties', and she said on 9/9 'take that off the table'.", "ev": "lecture"}], "src": ["VA:0:00-10:35", "W3A:slide 5", "L0909"]}, {"h": "Video 2: A decision-making process for selecting a diagnostic test", "visual": "decision", "body": ["A decision-making process is a systematic, step-by-step guide that organizes information and alternatives. The general cycle: identify the decision → gather information → identify alternatives → weigh evidence → choose → take action → **review the decision** (which restarts the cycle).", "For choosing a test to inform a **diagnosis**, the flowchart asks six questions. A 'no' on any of the first five means find another test."], "table": {"head": ["#", "Question", "What you check"], "rows": [["1", "Can I use this test for diagnosis?", "Purpose. The manual is the most likely place to find it. A screening test used for diagnosis is not a valid use; a manual stating a different purpose means it is not valid for yours."], ["2", "Is there acceptable evidence of diagnostic accuracy?", "Group differences, sensitivity/specificity, and the diagnostic system behind them."], ["3", "Does the normative sample reflect the person being tested?", "Representation in the standardization sample (for language: age, sex, language, dialect)."], ["4", "Does the test accurately measure the skill(s) relevant to the diagnosis?", "Four kinds of evidence: content, response process, relations with other variables, internal structure."], ["5", "Does the test consistently measure the person's ability?", "Administration consistency and reliability evidence: test-retest, alternate/parallel forms, interrater, internal consistency, standard error of measurement."], ["6", "Is this test sufficient for diagnostic decision-making?", "Need for converging evidence; guard against confirmation bias."]]}, "src": ["VB:0:00-7:10", "VB:46:54-48:24"]}, {"h": "Diagnostic accuracy, as the video teaches it", "body": ["A **diagnostic system** has three parts: the **index test** (the test under evaluation), the **target disorder**, and the **gold/reference standard**. A diagnostic accuracy study asks how well the index test identifies the presence and absence of the target disorder.", "**Sensitivity** = ability of the index test to identify the PRESENCE of the disorder; **specificity** = ability to identify its ABSENCE. You want both high. A statistically significant difference between control and disordered groups shows the test is sensitive 'to some degree' but is not the same as reporting sensitivity and specificity.", "Red flags when judging a study: the index test is **part of the reference standard battery** (no independent check); different reference standards for the disordered and control groups (a reporting standards document says all participants must have the same reference standard, to avoid bias); an ambiguous target-disorder definition.", "**Sensitive and specific to WHAT?** The digit-triplets-in-noise test showed 91% sensitivity and 93% specificity, but for **elevated pure-tone thresholds**, not for a speech-recognition-in-noise disorder. Accuracy values do not transfer to a different target disorder. In the same table, the bilateral pure-tone average detected only **28%** of people with a speech-recognition-in-noise disorder; the HINT composite showed 88% sensitivity / 77% specificity."], "callouts": [{"k": "textbook", "t": "Textbook Ch. 1 adds a benchmark: sufficient sensitivity and specificity are typically defined as .80 (80%) or higher.", "ev": "textbook"}], "src": ["VB:7:52-31:24", "TB1: relevant section reviewed for this topic"]}, {"h": "Does it measure the right skill? Four kinds of evidence", "table": {"head": ["Evidence", "Meaning in the video", "Example"], "rows": [["Content", "Items reviewed by content experts; all relevant domains covered (also called judgment validity)", "Experts confirm a language test assesses language, not speech"], ["Response process", "How the person answers must fit the skill measured", "Pointing is not an accurate response manner for speech or expressive language, but can be appropriate for receptive language"], ["Relations with other variables", "Strong correlation with tests of the same skill; weak with unrelated skills", "Receptive test A vs receptive test B: strong; vs a fine motor test: weak; vs speech sound production: may be moderate if the test requires spoken responses"], ["Structure", "Factor analysis / structural equation modeling: as many factors as skills claimed", "Receptive vocabulary: one factor; phonological awareness: multiple factors"]]}, "src": ["VB:32:52-40:38"]}, {"h": "Is it sufficient? Challenges to diagnostic accuracy", "body": ["Even an appropriate test may not be sufficient alone. Look for **converging evidence** (e.g., a perceptual motor-speech evaluation suggests lingual weakness, so do an oral mechanism exam to confirm). Watch **confirmation bias**: the adult-neurogenic saying 'by the time you give an aphasia test you already know someone has aphasia'.", "**Clinician / scientific-community challenges:** lacking or changing diagnostic classification schemes; skills needed to interpret responses (e.g., calibrated perceptual description of speech subsystems).", "**Patient challenges:** visual and hearing acuity, motor weakness, co-occurring communication disorders (don't blame language for unintelligibility caused by a motor speech disorder), fatigue, medication, test anxiety, premorbid ability (very high or low)."], "src": ["VB:41:57-46:54"]}], "concepts": ["m3-eba", "m3-problems", "m3-cases", "m3-questions", "m3-accuracy", "m3-validity-evidence", "m3-sufficiency"]}, {"id": "m04", "number": 4, "title": "Difference or disorder: multicultural assessment", "kicker": "Week 3 · Multicultural", "week": "Week 3 (+ 9/14 lecture)", "summary": "The Week 3 multicultural deck: your primary role, ASKED, ethnographic research, assessing CLD clients, dynamic assessment, test modifications, the disorder-vs-difference signs, and interpreters (BID).", "sections": [{"h": "Your primary role and where cultural knowledge comes from", "body": ["Slide 2: your **primary role is to determine disorder or difference**; set aside biases and stereotypes; know cultural communication differences (social rules, customs, beliefs).", "Slide 3 lists what cultural groups may view differently: disability and intervention; a woman's role in society; familial authority; appropriate names and titles; case history and interview questions; traditional testing practices; individual achievement; the child's behavior; use of eye contact; time; expression of disapproval; personal space; small talk; mistrust of other cultural groups.", "Slide 4: speech characteristics vary; know typical patterns for the client's background (Speech Accent Archive, George Mason University; Multilingual Children's Speech, Charles Sturt University, Australia).", "Slide 5, **ethnographic research** (a method of becoming more culturally knowledgeable): attend cultural events; watch movies and TV from the client's cultural group; read literature from the group; watch culturally representative video; ask the client to share; interview community members; consult other professionals; read professional literature. The ethnographic interview approach supplements it."], "callouts": [{"k": "lecture", "t": "9/14: she tied this to interviewing. Personal space varies by culture; if you stand closer than a family expects and they shut down, 'I would receive that as something disordered versus that might just culturally' be normal. She had the class rephrase badly worded questions (e.g., 'Does your child sit in front of a TV screen all day?' → 'How does your child spend screen time?').", "ev": "lecture"}], "src": ["W3B:slides 2-5", "L0914"]}, {"h": "Cultural competence: ASKED", "visual": "asked", "body": ["Slide 6: cultural competence enables clinicians to serve clients with knowledge, respect and dignity. It is an **ongoing process that requires self-assessment**. The conceptual model is **ASKED: Awareness, Skill, Knowledge, Encounters, Desire**. ASHA's Office of Multicultural Affairs (OMA) provides resources."], "src": ["W3B:slide 6"]}, {"h": "Assessing CLD clients", "body": ["Slide 7: the assessment is **thorough, individualized, evidence-based**, and **assesses abilities in both languages**. Considerations: culturally appropriate materials; **test in one language at a time**; be prepared to modify the assessment plan; use an interpreter/translator if needed; be sensitive and respectful.", "Slide 8: **language history** is a necessary component (which languages, how frequently). Textbook forms: **Form 3-2 'Language History Survey for Children'** and **Form 3-3 '...for Adults'**. Be thoughtful about how the information is obtained.", "Slide 9, **five direct-assessment approaches**: information from clients and others; observations; speech-language sample analysis; dynamic assessment; standardized testing.", "Slide 10: parents or family members **may be the best source**. The **Alberta Language and Development Questionnaire (ALDeQ)** is a parent questionnaire for ages **4;5 to 7;5**, available online. Classroom teachers help for school-aged clients; interpreters/translators are good sources of information."], "callouts": [{"k": "numbers", "t": "ALDeQ: parent questionnaire, ages 4;5-7;5. Textbook adds: norm-referenced; for children with 4-40 months of English exposure.", "ev": "slide"}], "src": ["W3B:slides 7-10", "TB3: relevant section reviewed for this topic"]}, {"h": "Dynamic assessment and standardized tests with CLD clients", "body": ["Slide 11: dynamic assessment is **widely recommended** for CLD clients. **Clients who do NOT demonstrate improvement are more likely to have a language impairment.**", "Slide 12: standardized tests are **often problematic** for CLD populations. Review materials first. Ways a test might be modified: **repeat or reword; add more trial questions; alter, rephrase or add test questions; score according to question intent; request clarifications.**"], "callouts": [{"k": "conflict", "t": "Tension to keep straight: Week 2 calls extra cues, altered instructions and translation MODIFICATIONS that can invalidate standard scores. Week 3 lists modifications you might make for CLD clients. Both are true: the modification can make the testing more useful, and the resulting standard score may no longer be valid for norm comparison. Report it.", "ev": "inference"}], "src": ["W3B:slides 11-12", "W2:slides 7-8"]}, {"h": "Disorder vs difference (slides 13-14)", "table": {"head": ["", "Pattern"], "rows": [["Disorder", "Client demonstrates difficulties in ALL languages"], ["Difference", "Difficulties present in only ONE language"]]}, "bullets": ["Signs indicative of disorder: difficulty learning both languages; atypical nonverbal communication; idiosyncratic communication errors; family history of language-learning disability; slower development; difficulty expressing basic needs; difficulty with peer interactions, asking/answering questions, conveying thoughts; tendency to repeat what is heard.", "A speech-language disorder in both languages warrants intervention.", "Elective therapy such as accent modification; the client may benefit from community programs."], "callouts": [{"k": "trap", "t": "Antonym-flip target: 'difficulties in only one language = disorder'. Also: 'tendency to repeat what is heard' is on the DISORDER list.", "ev": "inference"}, {"k": "gonsoulin", "t": "Her 4382 record included CLD assessment (disorder within difference; interpreters over family). Historical overlap only.", "ev": "historical"}], "src": ["W3B:slides 13-14", "CODEX:section 9"]}, {"h": "Interpreters, translators and BID (slides 15-16)", "visual": "bid", "body": ["**Interpreters translate spoken language; translators translate written text.** IDEA guidelines: clients/caregivers who use a language other than English must be provided services in their **primary language**.", "Select an interpreter/translator who: is proficient in English and the client's primary language; is experienced and trained in cross-cultural communication; has training and knowledge of issues relevant to SLP; will remain unbiased and confidential.", "**BID three-phase process (Langdon & Saenz, 2016):** **Briefing** (review agenda and purposes; discuss technical information; train the interpreter) → **Interaction** (introduce client to interpreter, **remain in the room and observe** the interpreter; **talk to the client, not the interpreter**; brief sentences, natural rate) → **Debriefing** (discuss difficulties and impressions; review assessment information; plan follow-up and provide additional training)."], "src": ["W3B:slides 15-16", "TB3: relevant section reviewed for this topic"]}], "concepts": ["m4-role", "m4-asked", "m4-cld", "m4-da-std", "m4-diff", "m4-interp"]}, {"id": "m05", "number": 5, "title": "Assessment methods and the rules of standardized testing", "kicker": "Week 2 · Methods", "week": "Week 2", "summary": "The five assessment methods, what goes under each, why you read the manual first, and the accommodation-vs-modification line.", "sections": [{"h": "Purpose and the five methods", "body": ["Slide 2: the purpose of an assessment is **to draw a conclusion about an individual's communicative abilities**; there are many different paths.", "Slide 3 names **five methods**: information from clients and others; observation; speech-language analysis; dynamic assessment; standardized assessments."], "table": {"head": ["Method", "What she lists under it (slide 4)"], "rows": [["Information from clients and others", "Case history forms; questionnaires and inventories; rating scales; checklists; interviews (traditional and ethnographic)"], ["Observations", "Naturalistic; systematic observation and contextual analysis; simulated observations and structured play"], ["Speech-language sample", "(analysis of connected speech/language)"], ["Dynamic assessment", "(test-teach-retest; Week 5)"], ["Standardized tests", "Norm-referenced tests; criterion-referenced tests"]]}, "callouts": [{"k": "textbook", "t": "Textbook Ch. 1: a traditional interview is controlled by the clinician; an ethnographic interview is guided by the clinician but controlled, in part, by the informant. Questionnaires need simple answers; inventories are more detailed.", "ev": "textbook"}], "src": ["W2:slides 2-4", "TB1: relevant section reviewed for this topic"]}, {"h": "Before administering any standardized test", "body": ["Slide 5 (the STOP sign): **READ THE ACCOMPANYING MANUAL.** Know the **purpose** of the test, the **population** for whom it is designed, **review psychometric properties**, and **learn how to administer it correctly**.", "Slide 6 lists the steps of administering and interpreting: accommodations and modifications; determining chronological age; basals and ceilings; obtaining a raw score; normative data; understanding normed scores; confidence intervals."], "callouts": [{"k": "lecture", "t": "9/2 (Assessment Detective walk-through): she had you check the manual for purpose, content, norms (size, geographic locations, SES), reliability, clear instructions, scoring procedures and conversion tables. Your PPVT-5 submission applied the same checklist.", "ev": "lecture"}], "src": ["W2:slides 5-6", "L0902", "AD", "PPVT"]}, {"h": "Accommodation vs modification (slides 7-8)", "visual": "accmod", "table": {"head": ["", "Accommodation", "Modification"], "rows": [["Changes", "HOW the test is administered", "WHAT is being measured (or the protocol enough to break norm comparison)"], ["Standard scores", "Generally remain valid", "May become invalid"], ["Examples", "Breaks, quiet room, assistive devices (hearing aids/FM), enlarged stimuli", "Extra cues/prompts not in the manual, repeating items when not allowed, altered instructions, translated items, a different response format"], ["Construct", "Does not alter the construct", "Alters the construct or administration protocol"]]}, "body": ["Her examples: a student with a hearing impairment takes the CELF in a quiet room wearing hearing aids; items, instructions and scoring unchanged → **accommodation**. On an articulation test the examiner says 'Remember your /r/ sound' when the manual does not allow cues → **modification**."], "callouts": [{"k": "textbook", "t": "Textbook lists 'allow extra time on timed tests' as a modification. Breaks are her accommodation example. Keep 'break between items' and 'more time on a timed item' apart.", "ev": "textbook"}, {"k": "trap", "t": "Allowing responses in a different format than the test requires = modification (slide 7), even though it sounds like access.", "ev": "slide"}], "src": ["W2:slides 7-8", "TB1: relevant section reviewed for this topic"]}, {"h": "Norm-referenced vs criterion-referenced", "body": ["Both appear under Standardized Tests on slide 4. The textbook explains the contrast: a **norm-referenced** test answers 'How does my client compare to the average?' (always standardized); a **criterion-referenced** test answers 'How does my client's performance compare to an expected level of performance?' (used most often for neurogenic, fluency and voice disorders). 'Standardized' and 'norm-referenced' are not synonyms: any test can be standardized if administration and scoring are uniform."], "callouts": [{"k": "gonsoulin", "t": "COMD 4382 record: norm vs criterion vs dynamic appeared as an EXCEPT item. Historical overlap only.", "ev": "historical"}], "src": ["W2:slide 4", "TB1: relevant section reviewed for this topic", "CODEX:section 9"]}], "concepts": ["m5-methods", "m5-manual", "m5-accmod", "m5-normcrit"]}, {"id": "m06", "number": 6, "title": "Age, basals, ceilings and the raw score", "kicker": "Week 2 · Administration", "week": "Week 2", "summary": "Chronological and adjusted age (including the borrowing-convention conflict), basal and ceiling rules, and why the raw score is the bridge to every other number.", "sections": [{"h": "Chronological age", "body": ["Slide 9: determining CA is a critical step because scores must be compared with the **correct age-based normative group**. Her 'Clinical Bottom Line': **if the age is wrong, every age-based score derived from the test may also be wrong**, which can lead to incorrect clinical decisions.", "Slide 12 lists online calculators (SLP Chronological Age Calculator, which reports ages in SLP format like 6;4 = 6 years, 4 months; Home Speech Home; FreeSLP; WiseAgeCalc; Speech Therapist Tools).", "**Hand calculation.** Write the test date and birth date as year / month / day and subtract, days first. If the test day is smaller, borrow a month (add days, reduce the month by 1). If the month is then smaller, borrow a year (add 12 months, reduce the year by 1)."], "visual": "ca", "callouts": [{"k": "conflict", "t": "GENUINE CONFLICT, not reconciled here. How many days does a borrowed month add? (1) Her COMD 4382 practice key used a fixed 30-day borrow; the codex verified one item where a 31-day borrow gave an answer that was not among the options (historical, her key). (2) The course textbook (Ch. 1) says borrow '30 or 31 days (based on number of days in month borrowed from)'. (3) Her current Week 2 slides give no borrowing rule and point to online calculators, which use real calendar days. Practice items in this lab either avoid day-borrowing or state the convention in the stem. If she gives a CA problem, ask which convention she wants, or look at whether only one answer choice is possible.", "ev": "historical"}, {"k": "numbers", "t": "SLP notation: 6;4 = 6 years, 4 months. Full CA is years;months;days.", "ev": "slide"}], "src": ["W2:slides 9, 12", "TB1: relevant section reviewed for this topic", "CODEX:section 8"]}, {"h": "Adjusted (corrected) age", "body": ["Slides 10-11: adjusted age is the age a child would be if born on the **due date**. Used mainly for **premature infants** (speech, language, feeding, early communication). Without it, a preterm infant compared to same-age peers may **appear delayed** when development is appropriate for the time they have had; using it helps **avoid over-identifying delays**.", "**Adjusted age = chronological age − weeks (or months) premature.** Her example: DOB January 1, 2026; due date March 1, 2026; born 8 weeks early. Assessed September 1, 2026: CA 8 months; prematurity 2 months (8 weeks); **adjusted age 6 months**."], "callouts": [{"k": "textbook", "t": "Textbook: adjusted age becomes less relevant as a child grows and is generally not a consideration for children over age 3. It gives a similar example: a 10-month-old born 8 weeks early is developmentally more like an 8-month-old.", "ev": "textbook"}], "src": ["W2:slides 10-11", "TB1: relevant section reviewed for this topic"]}, {"h": "Basals and ceilings (slides 13-14)", "table": {"head": ["", "Basal", "Ceiling"], "rows": [["Definition", "Point at which you can assume the examinee would have answered all EASIER items correctly", "Point at which you can assume the examinee would miss increasingly DIFFICULT items"], ["Purpose", "Don't waste time on too-easy items; reduce fatigue and frustration; establish a starting point", "Don't administer too-difficult items; reduce stress and discouragement; save time; estimate highest level of performance"], ["Her examples", "Slide 13: 5 consecutive correct (credit all preceding items). Slide 14: 4 consecutive correct", "Slide 13: 5 consecutive incorrect (missed items 28-32 → stop). Slide 14: 4 consecutive incorrect"], ["Nickname (slide 14)", "'Start confidence'", "'Stop point'"]]}, "body": ["Slide 14 clinical example: a 9-year-old answers items 10-13 correctly → **basal established**; continues testing; misses items 27-30 consecutively → **ceiling established**. The examiner credits all items below the basal, stops at the ceiling, and calculates the raw score using the manual. Together they find the client's **zone of performance**."], "callouts": [{"k": "numbers", "t": "The counts are TEST-SPECIFIC. Her two examples use 5 and 4. Your PPVT-5 assignment found basal = 3 consecutive correct and ceiling = 6 consecutive incorrect for that test. Checked against Pearson's PPVT-5/EVT-3 'What's changed' sheet: 3 consecutive correct / 6 consecutive incorrect on continuous items (the PPVT-4 used 12-item sets). The slide numbers are examples, not PPVT-5 rules.", "ev": "assignment"}], "src": ["W2:slides 13-14", "PPVT"]}, {"h": "Raw score", "body": ["Slide 15: a raw score is the **total number of points earned** on a test according to the manual's scoring rules. It is **the bridge between test performance and interpretation**. If it is wrong because of administration or scoring errors, **every score derived from it may also be inaccurate**, potentially affecting diagnosis, eligibility and treatment planning."], "callouts": [{"k": "gonsoulin", "t": "COMD 4382 record: 'Scoring the PPVT-5, first identify the raw score. Standard score requires raw score + chronological age.' Historical item, consistent with slides 9 and 15.", "ev": "historical"}, {"k": "textbook", "t": "Textbook: raw scores alone are not diagnostically meaningful; they are converted to other metrics.", "ev": "textbook"}], "src": ["W2:slide 15", "CODEX:section 4 T5", "TB1: relevant section reviewed for this topic"]}], "concepts": ["m6-ca", "m6-adjusted", "m6-basal", "m6-raw"]}, {"id": "m07", "number": 7, "title": "Norms, score scales and her bell curve", "kicker": "Week 2 · Numbers", "week": "Week 2 (+ 9/2 lecture)", "summary": "Her score table and bell-curve slide are the numerical conventions for this course. Learn the scales, the band boundaries, percentiles, age equivalents and confidence intervals, and where the textbook disagrees.", "sections": [{"h": "Normative data (slide 16)", "body": ["Normative data = performance information collected from **a large group of individuals who represent the population for whom a test was designed**; their scores become the test's norms. Four reasons it matters: **allows comparison to peers; makes standardized scores possible; supports diagnostic and eligibility decisions; helps determine whether performance is 'typical'.**"], "src": ["W2:slide 16"]}, {"h": "Her score table (slide 17)", "table": {"head": ["Score type", "Mean", "SD", "Her example"], "rows": [["Standard score", "100", "15", "115 is 1 SD above average; 85 is 1 SD below. Most standardized tests use this metric."], ["Standard deviation", "N/A", "N/A", "With mean 100 and SD 15, scores from 85-115 fall within 1 SD of the mean."], ["Percentile rank", "50th", "N/A", "% of the norm group scoring AT OR BELOW a score. 75th = performed as well as or better than 75%."], ["Scaled score", "10", "3", "Used for subtests. 13 = 1 SD above; 7 = 1 SD below."], ["z score", "0", "1", "+2.0 = two SDs above; −1.0 = one SD below."], ["Stanine", "5", "2", "Nine categories. 5 = average; 7-9 = above average; 1-3 = below average."], ["Age equivalent", "N/A", "N/A", "Age at which the raw score is typical. Descriptive; NOT for eligibility or severity."]]}, "callouts": [{"k": "numbers", "t": "Same position, different scales: SS 85 = scaled 7 = z −1. SS 70 = scaled 4 = z −2. SS 115 = scaled 13 = z +1. Slide 21: standard scores, z scores, scaled scores and stanines all express the same underlying performance relative to a norm group.", "ev": "slide"}, {"k": "conflict", "t": "Stanines 4 and 6 are not labeled on her slide (5 = average, 7-9 above, 1-3 below). The textbook says 54% of people score 4, 5 or 6. This lab does not key a band label for stanine 4 or 6.", "ev": "textbook"}], "src": ["W2:slides 17, 21", "TB1: relevant section reviewed for this topic"]}, {"h": "The bell curve she showed (slide 18)", "visual": "bell", "body": ["Her slide 18 image labels the bands and anchors. This is the course's numerical convention for describing standard scores:"], "table": {"head": ["Band on her slide", "Standard scores", "SD", "Percentile anchors"], "rows": [["Significantly below average", "below 70", "beyond −2 SD", "70 ≈ 2nd; 55 ≈ <0.1"], ["Below average", "70 to 85", "−2 to −1 SD", "85 ≈ 16th"], ["Average", "85 to 115", "−1 to +1 SD", "100 = 50th"], ["Above average", "115 to 130", "+1 to +2 SD", "115 ≈ 84th"], ["Significantly above average", "above 130", "beyond +2 SD", "130 ≈ 98th; 145 ≈ >99.9"]]}, "callouts": [{"k": "numbers", "t": "Boundary rules used in this lab: 85 and 115 are AVERAGE (slide 17: 'scores from 85-115 fall within 1 SD'; the textbook: average range 85-115, below 85 is below average, above 115 is above average). So 84 = below average, 116 = above average, 71 = below average, 69 = significantly below average.", "ev": "slide"}, {"k": "conflict", "t": "Exactly 70 and exactly 130 sit ON the ±2 SD lines of her picture, and the slide does not say which band owns the line. The textbook says −2 SD is 'a standard score of 70 or below'. This lab never keys a band for exactly 70 or 130; know that they are the −2 SD and +2 SD points.", "ev": "slide"}, {"k": "conflict", "t": "Second genuine conflict: the textbook (Ch. 1) says performance −1.5 to −2 SD below the mean is 'usually considered significantly below average' (−1.5 SD = SS 77.5, scaled 5.5). Her slide labels 70-85 'Below Average' and reserves 'Significantly Below Average' for below 70. For her class, the lab uses her slide's labels.", "ev": "textbook"}, {"k": "lecture", "t": "9/2: 'Is he significantly below average, or is he just below average? Because those are two different' things. Where the patient lands relative to the norm is 'the important part from the diagnostic' standpoint.", "ev": "lecture"}], "src": ["W2:slides 17-18", "L0902", "TB1: relevant section reviewed for this topic"]}, {"h": "Percentiles, age equivalents and eligibility (slides 17, 21)", "bullets": ["Percentile rank = percentage of the norm group scoring **at or below** a score. It is not percent correct.", "**Percentile ranks are often easiest for parents and clients to understand.**", "Standard deviations help clinicians determine how far a score is from average.", "**Age equivalents** should be interpreted cautiously; they do not represent overall ability and often overstate or understate performance. They should not be used to determine eligibility or severity.", "**Most eligibility decisions** in clinical and educational settings are based on **standard scores and standard deviations**, not age equivalents."], "callouts": [{"k": "lecture", "t": "9/2: our field is moving away from age equivalents, though you will still see them on tests; they don't always capture the skill, and they won't qualify a child or satisfy insurance.", "ev": "lecture"}], "src": ["W2:slides 17, 21", "L0902"]}, {"h": "Confidence intervals (slides 19-20)", "body": ["A **confidence interval** is a range of scores around the obtained score that reflects the possibility of **measurement error**. If the same person took the test multiple times, the score might vary slightly. Why they matter: no test score is perfectly 'exact'; a more accurate picture of ability; better clinical decisions; supports evidence-based assessment."], "table": {"head": ["Confidence level", "Her slide"], "rows": [["68%", "Less conservative, narrower range"], ["90%", "Commonly reported"], ["95%", "Most commonly used clinically"], ["99%", "Most conservative, widest range"]]}, "callouts": [{"k": "numbers", "t": "As confidence INCREASES, the interval gets WIDER (more certainty that the true score is inside).", "ev": "slide"}, {"k": "conflict", "t": "Course wording vs psychometrics: her slide 19 says 'Confidence intervals increase the reliability of the test' (she said it in the 9/2 lecture too, and the textbook uses the same sentence). Technically an interval expresses measurement error; it does not change a test's reliability coefficient. If the exam quotes the slide sentence, her source says True. Know both.", "ev": "slide"}, {"k": "textbook", "t": "Textbook: CIs are especially useful for borderline scores; reporting a range can place a client in the below-average range and help justify therapy when other data agree.", "ev": "textbook"}], "src": ["W2:slides 19-20", "L0902", "TB1: relevant section reviewed for this topic"]}], "concepts": ["m7-norms", "m7-scales", "m7-bands", "m7-percentile", "m7-ae", "m7-ci"]}, {"id": "m08", "number": 8, "title": "Psychometrics: can the result be trusted?", "kicker": "Week 2 · Quality", "week": "Week 2 (+ textbook Ch. 1)", "summary": "Her six properties of a quality assessment and their one-line questions, then the textbook's types of validity, reliability and bias, and the sensitivity/specificity direction logic.", "sections": [{"h": "Her six properties (slides 23-24)", "body": ["**Psychometrics:** the science of measuring human characteristics, abilities and behaviors. A quality assessment must be:"], "table": {"head": ["Property", "Definition on slide 23", "Bottom-line question (slide 24)"], "rows": [["Valid", "Measures the intended construct", "Is it measuring the right thing?"], ["Reliable", "Produces consistent results", "Are the results consistent?"], ["Standardized", "Administered and scored uniformly", "Was it given the same way to everyone?"], ["Unbiased", "Fair for all individuals and populations", "Is it fair?"], ["Sensitive", "Correctly identifies individuals who HAVE the condition", "Can it detect a problem when it's present?"], ["Specific", "Correctly identifies individuals who do NOT have the condition", "Can it rule out a problem when it's absent?"]]}, "callouts": [{"k": "source", "t": "Bottom line: if a test is not valid, reliable, standardized, sensitive and specific, and free from bias, the results cannot be trusted for accurate decision-making.", "ev": "slide"}, {"k": "lecture", "t": "9/2: she framed it as a patient: would you accept surgery on a test that identifies the problem only about 60% of the time? 'Always put yourself into the situation.'", "ev": "lecture"}], "src": ["W2:slides 23-24", "L0902"]}, {"h": "Types of validity and reliability (textbook Ch. 1)", "table": {"head": ["Type", "Meaning"], "rows": [["Face validity", "Looks like it tests the skill; a layperson can judge; not valuable alone"], ["Content validity", "Contents represent the domain; judged by experts (e.g., an articulation test eliciting all phonemes in their contexts)"], ["Construct validity", "Measures the theoretical construct (e.g., scores rise with age in typical children)"], ["Criterion validity: concurrent", "Compares to an established standard"], ["Criterion validity: predictive", "Predicts later performance (e.g., SAT → college)"], ["Test-retest reliability", "Stability over time: same test, same group, repeated"], ["Internal consistency (split-half)", "One half of the test correlates with the other half"], ["Intrarater / interrater reliability", "Same rater on different occasions / different raters agree"], ["Alternate-form (parallel-form) reliability", "Form A vs parallel Form B with the same group"]]}, "callouts": [{"k": "assignment", "t": "Your PPVT-5 detective work: reliability .97 overall, test-retest .88, alternate forms .84; validity correlations .77 with EVT-3 and .68 with CELF-5 Core Language (concurrent-type evidence). Correlations and reliability coefficients are NOT sensitivity and specificity.", "ev": "assignment"}], "src": ["TB1: relevant section reviewed for this topic", "PPVT"]}, {"h": "Sensitivity and specificity: direction", "visual": "sensspec", "body": ["Fix the TRUE status first. Among people who HAVE the disorder, how many does the test catch? → **sensitivity** (misses = false negatives). Among people who do NOT have it, how many does the test clear? → **specificity** (errors = false positives).", "Low sensitivity → disorders get missed (**under-identification**). Low specificity → typical people get flagged (**over-identification**). Textbook benchmark: .80 (80%) or higher is typically considered sufficient."], "callouts": [{"k": "gonsoulin", "t": "COMD 4382 record: 'If an assessment has high specificity but low sensitivity, what's the impact?' (answer: under-identifies). Historical item type.", "ev": "historical"}], "src": ["W2:slides 23-24", "TB1: relevant section reviewed for this topic", "CODEX:section 6"]}, {"h": "Freedom from bias (textbook)", "bullets": ["**Item bias**: individual items favor one group over another.", "**Intrinsic test bias**: the test generally favors one group; groups obtain different mean scores.", "**Extrinsic test bias**: group outcome differences come from societal differences, not the test itself."], "src": ["TB1: relevant section reviewed for this topic"]}], "concepts": ["m8-six", "m8-types", "m8-sensspec", "m8-bias"]}, {"id": "m09", "number": 9, "title": "Overview of a complete assessment", "kicker": "Week 3 · Evaluation", "week": "Week 3 (+ lectures 9/9, 9/11)", "summary": "Why quality matters, how setting shapes the evaluation, the core components (including the hearing screen), case history, intake interview phases, internal and external influences, direct assessment and play-based assessment, and why formal AND informal measures matter.", "sections": [{"h": "Quality and scope (slides 2-3)", "body": ["Slide 2: the **quality** of an evaluation determines everything that follows. A thorough assessment produces **specific, defensible goals** and a clear therapy trajectory; a weak one produces **vague objectives, slow progress, and documentation that falls apart under insurance review or IEP scrutiny**.", "Slide 3: an evaluation is **more than a single test score**: a comprehensive process to capture how a person communicates across real-life contexts, identify the **nature and severity** of any disorder, and lay the groundwork for treatment. **ASHA's Preferred Practice Patterns** (originally approved in **2004**, still current) align evaluation with the **WHO International Classification of Functioning, Disability and Health (ICF)**, so clinicians consider not just impairment-level data but how communication difficulties affect **participation in daily activities**."], "callouts": [{"k": "lecture", "t": "9/9 example: a trial attorney with dysarthria after a stroke. The impairment may be mild, but its effect on his ability to be understood by a jury is a significant functional impact. That is the ICF lens.", "ev": "lecture"}], "src": ["W3A:slides 2-3", "L0909"]}, {"h": "Setting and population (slide 4)", "table": {"head": ["Setting", "What the evaluation centers on"], "rows": [["School", "Whether communication difficulties ADVERSELY AFFECT EDUCATIONAL PERFORMANCE; curriculum-based language sampling and classroom observations alongside standardized testing"], ["Outpatient clinic", "A broader range of functional outcomes; a preschooler referred for articulation gets a very different battery than an adult assessed for aphasia after a neurological event"], ["Hospital / acute care", "More targeted and time-sensitive: a bedside swallowing screen or brief cognitive-linguistic assessment may take priority; comprehensive evaluation once the patient stabilizes"]]}, "callouts": [{"k": "lecture", "t": "9/9: after a stroke, doctors want to know if the patient is safe to swallow. The SLP does a bedside swallow screen (liquids, puree, a cracker); if it fails, further testing such as a modified barium swallow.", "ev": "lecture"}], "src": ["W3A:slide 4", "L0909"]}, {"h": "Core components (slide 5)", "bullets": ["Case history", "Interviews", "Direct assessment: oral motor examination; standardized (formal) testing; informal measures (language samples, dynamic assessment, narrative re-tell tasks); **hearing screening** (because hearing loss can mimic or compound speech-language difficulties, a screening is typically included or recent audiological results are reviewed); observations (eye contact, turn-taking, attention, frustration tolerance, self-correction patterns)", "Analysis of findings", "Writing reports", "Sharing findings"], "callouts": [{"k": "lecture", "t": "9/9: kids who come in with a language delay may have a hearing loss, so 'take that off the table'. The textbook adds: an SLP screens; a client who fails is referred to an audiologist or other medical professional; SLPs do not diagnose hearing loss.", "ev": "lecture"}, {"k": "source", "t": "Hearing-loss degree tables are NOT part of this lab. No Diagnostics slide, announcement or transcript in your package defines degree ranges, so the lab does not invent or import one.", "ev": "inference"}], "src": ["W3A:slide 5", "L0909", "TB4: relevant section reviewed for this topic"]}, {"h": "Case history (slides 6-8)", "body": ["The case history influences the **choice of assessment tools and strategies** and enhances understanding of the disorder. It records past and present concerns. Histories: **developmental, medical, family, professional evaluations, occupational, educational, sociological**. It provides a **starting point** for assessment but **may be limited due to potential problems** (e.g., an informant who cannot report accurately).", "Slide 8: **allergy awareness** (important if allergens could be used during assessment or treatment). **Information from other professionals** (SLPs, audiologists, doctors, teachers, psychologists, OT/PT, counselors) **may lead to a biased view** of the client's condition."], "callouts": [{"k": "lecture", "t": "9/9: you can agree or disagree with another professional's report, but 'you have to do your own independent testing'. Case history and interview often happen at the same time; intake forms or chart review may arrive before the visit.", "ev": "lecture"}, {"k": "lecture", "t": "9/14: why developmental milestones matter: if motor milestones were on time but speech/language were late, that points to a speech-language issue; if everything is delayed, think broader and early intervention (under 36 months). Pneumonia history can be a red flag for aspiration.", "ev": "lecture"}], "src": ["W3A:slides 6-8", "L0909", "L0914"]}, {"h": "Interviews (slides 9-10)", "visual": "intake", "body": ["To conduct effective interviews: **use open-ended questions** to encourage detailed responses; **listen actively and take detailed notes**; **clarify inconsistencies** or unclear information; **be sensitive** to concerns and emotions.", "Intake interview phases: **Opening** (introductions; purpose of meeting; structure of meeting) → **Body** (major content areas) → **Closing** (summarize major points)."], "callouts": [{"k": "lecture", "t": "9/9: she introduces herself, explains they'll talk first and then do testing, covers history in the body, and closes by summarizing and saying what comes next. Research she cited: for young children (birth to 3), parent-reported information is often more accurate than what you see in the clinic, since toddlers often won't perform on the spot.", "ev": "lecture"}], "src": ["W3A:slides 9-10", "L0909"]}, {"h": "Internal and external influences (slide 11)", "table": {"head": ["Internal (physical and mental limitations)", "External (can influence the assessment)"], "rows": [["Cognition and communication", "Family environment"], ["Motor abilities and strength", "Linguistic factors"], ["Hearing and visual acuity", "Cultural influences"]]}, "src": ["W3A:slide 11"]}, {"h": "Direct assessment and play-based assessment (slide 12)", "bullets": ["Multiple approaches will be employed.", "**The more direct assessment information the clinician obtains, the stronger the conclusions will be.**", "Choose approaches that will validly and reliably assess behaviors of concern.", "Apply modifications **when necessary**.", "Account for cultural-linguistic factors.", "**Play-based assessment**: use of toys and activities; following the child's lead; **suitable for children with limited English proficiency**."], "callouts": [{"k": "lecture", "t": "9/11: play-based assessment lets you observe how a child interacts without interfering; she described warming up a reluctant child with play before formal testing.", "ev": "lecture"}], "src": ["W3A:slide 12", "L0911"]}, {"h": "Formal AND informal (slides 13-14)", "body": ["Standardized scores have well-documented limitations: **a child might score in the average range on a vocabulary test yet struggle to hold a conversation with peers**; **an adult recovering from a stroke might perform poorly on a timed naming task yet communicate effectively using compensatory strategies**.", "**ASHA's Scope of Practice (2016)** explicitly recommends **multiple data sources**; **ASHA's Medical Review Guidelines** say to **avoid basing a diagnosis on a single standardized score**. Informal measures fill the gaps by showing how communication functions in everyday situations.", "Slide 14 asks two questions of your reports: do they describe the **functional communication impact, not just test scores**? Are you connecting findings to **real, observable communication demands** (ordering at a restaurant, following multi-step classroom directions)? Functional impact strengthens eligibility decisions and justifies services to insurance payers."], "src": ["W3A:slides 13-14", "L0911"]}], "concepts": ["m9-quality", "m9-setting", "m9-components", "m9-history", "m9-interview", "m9-influences", "m9-direct", "m9-formalinformal"]}, {"id": "m10", "number": 10, "title": "Analyze, diagnose, report, share", "kicker": "Week 3 · Conclusions", "week": "Week 3 (+ 9/11 lecture)", "summary": "Assimilating findings in the context of the case history, the three possible outcomes, what a treatment plan contains, the seven report sections, the results conference, and electronic sharing (EMR vs EHR).", "sections": [{"h": "Assimilate and analyze (slides 15-16)", "body": ["Slide 15 'deep analysis' feeds: make diagnosis, determine progress, recommend a treatment plan, establish realistic goals. Consider client input; score standardized tests; analyze speech-language samples; analyze results of dynamic assessment; analyze observations; consider influences that will contribute to **prognosis**.", "Slide 16: often **the most time-consuming** portion of the assessment. Findings should always be considered in the context of the **case history**, which helps you interpret results in light of medical, developmental and educational history, identify potential underlying causes, and develop a more accurate diagnosis. Her chain: **Case history: hearing loss → Assessment results: speech sound disorder → Diagnosis: SSD secondary to hearing loss → Treatment plan: SSD therapy and auditory rehabilitation.**"], "callouts": [{"k": "lecture", "t": "9/11: analysis looks for trends where different measures support one another; the same analysis is used for annual re-evaluations to determine progress. Her example of prognosis: a child who was typical until an abusive head injury.", "ev": "lecture"}], "src": ["W3A:slides 15-16", "L0911"]}, {"h": "Diagnosis and recommendations (slide 17)", "body": ["The goal of assessment. Outcomes typically fall into one of **three scenarios**: (1) a communicative disorder is diagnosed and a treatment plan recommended; (2) a disorder is diagnosed, a treatment plan recommended, **and further testing recommended**; (3) the client performs **within normal limits**.", "**Diagnosis → clinical label. Treatment plan → intervention strategy.** Elements of a treatment plan: **frequency, duration of sessions, environment, goals.**"], "callouts": [{"k": "textbook", "t": "Textbook: scenarios one and two are the most common outcomes; with scenario three, follow-up or referral may or may not be recommended.", "ev": "textbook"}], "src": ["W3A:slide 17", "TB2: relevant section reviewed for this topic"]}, {"h": "Diagnostic report (slide 18)", "table": {"head": ["Section", "Contents"], "rows": [["Identifying information", "Client name, date of birth, date of evaluation, referral source, clinician's credentials"], ["Reason for referral", "Concise statement of why the evaluation was requested and by whom"], ["Background and history", "Developmental, medical, educational, social history from interviews, records, prior reports"], ["Assessment procedures", "List of all formal tests, informal measures, observations, language samples"], ["Results by domain", "Findings by communication area with quantitative data AND qualitative descriptions"], ["Clinical impressions", "Synthesis into a cohesive profile, including severity ratings and functional impact statements"], ["Recommendations", "Therapy recommendations, referrals, frequency and duration, accommodations or home strategies"]]}, "callouts": [{"k": "trap", "t": "Severity ratings live in Clinical Impressions, not Results by domain. Frequency and duration live in Recommendations.", "ev": "slide"}], "src": ["W3A:slide 18"]}, {"h": "Sharing findings (slides 19-20)", "bullets": ["Share with the client, caregiver and others involved in care, in an information-sharing meeting (online, in person, phone).", "Review the written report; use **jargon-free language**, illustrations, charts, diagrams.", "Sensitivity to feelings; allow time to process; **emphasize the client's strengths**; ask questions that let the client/caregiver participate; **end by discussing next steps**.", "Electronic sharing is the **most efficient** method. Emailing reports: **PHI and privacy are an ethical and legal priority**.", "**EMRs** are digital versions of a client's medical records; **EHRs** are similar, but records can be **shared by professionals across health care organizations**."], "src": ["W3A:slides 19-20"]}], "concepts": ["m10-analyze", "m10-outcomes", "m10-report", "m10-share"]}, {"id": "m11", "number": 11, "title": "The interview in practice: Assignment 1", "kicker": "Week 4 · Mock interviews", "week": "Week 4 (+ 9/14 lecture)", "summary": "Common intake questions, interview structure, ethnographic wording, and clinically relevant follow-up when a young child is not talking.", "sections": [{"h": "Common intake interview questions (Week 4, slide 3)", "body": ["**Maintain an ethnographic interview mindset.** General questions often relate to: the **primary concern**; **when** the behavior became a concern; **progression** of the behavior; **suspicions about the cause**; **change** in the behavior; **consistency** of the behavior; **responses to** the behavior; **attempts to improve** it; **involvement of other professionals**; **expectations** of the evaluation."], "callouts": [{"k": "lecture", "t": "9/14 (going through an online case-history form): who lives in the household (a grandparent may be the afternoon caregiver you need to coach); language exposure; who referred; when the problem was first noticed (a year and a half of worry vs 'first noticed this week' changes the picture); whether the child is aware of the problem; what the family thinks caused it; family history (genetic component).", "ev": "lecture"}], "src": ["W4:slide 3", "L0914"]}, {"h": "The 20-minute mock interview (her handout)", "visual": "interview", "table": {"head": ["Minutes", "Segment", "Examples of her questions"], "rows": [["0-2", "Introduction & rapport", "'Can you tell me a little about the child?' 'What brings you in for an evaluation today?' 'What are your biggest concerns?' Remember: start broad before moving to specific questions."], ["2-7", "Speech & communication concerns", "When first noticed? Who noticed? Which sounds or words? How well do you vs unfamiliar people understand him? Different in different situations? Frustration? School/friendships?"], ["7-11", "Language & social communication", "Receptive (understand, follow directions, questions/stories); expressive (wants/ideas, complete sentences, tell about events, vocabulary/word finding); social (interact with adults/children, conversations, friends)"], ["11-15", "Developmental, medical & hearing history", "Full-term? Pregnancy/delivery complications? Milestones? Loss of skills? Medical history; frequent ear infections; hearing tested; ear tubes; medications; previous evaluations and services"], ["15-18", "School, family & parent priorities", "Teacher report; IEP/school services; academic concerns; languages at home; family history of speech, language, hearing or learning difficulties; strengths; what would you most like to see improve?"], ["18-20", "Summarize & close", "'Let me make sure I understand...' Include: 1 primary concern, 2 when it began, 3 functional impact, 4 relevant developmental/medical/hearing history, 5 parent's priorities. Then: 'Did I summarize that accurately? Is there anything else...?'"]]}, "body": ["Your role per the handout: you do **not** need to ask every question. **Prioritize** questions that help you understand the referral concern and determine what additional assessment may be needed. **Use open-ended questions first, then specific follow-ups.** Follow-up prompts: 'Can you give me an example?' 'How often does that happen?' 'What happens when he isn't understood?' 'What does his teacher report?'"], "src": ["MOCKX:pp. 1-6", "L0914"]}, {"h": "How she wants you to talk to families (9/14)", "bullets": ["**Active listening**: focus on the speaker, eye contact, affirm, show you are present; positive affect; open-ended questions; follow-up questions.", "Avoid negative connotations: ask 'What changes have you observed since the stroke?' rather than a leading negative.", "**Ethnographic sensitivity**: rephrase questions that judge. She had the class fix poorly worded ones, e.g., 'Does your child sit in front of a TV screen all day?' and 'Why did you wait so long before you brought him in?' (instead: ask about screen time neutrally; thank them for coming and ask whether they had any apprehensions).", "When a parent asks 'what caused this?': it is often too complex to pin on one thing; look at the whole picture; show compassion ('Nobody knows that answer, but we're going to do all the things we need to do to help').", "Summarize at the end so the parent can correct your understanding."], "src": ["L0914"]}, {"h": "A history finding changes the next question", "body": ["For a young child with limited speech and recurring ear infections, clarify onset, language use and function, then verify current hearing status rather than assuming that a caregiver’s report establishes normal hearing. Ask open questions first and use specific follow-up to investigate relevant findings."], "src": ["Week 3 complete-evaluation slide 5", "Current interview assignment: clinical-history principle"]}], "concepts": ["m11-questions", "m11-structure", "m11-cases", "m11-skills"]}, {"id": "m12", "number": 12, "title": "Standard precautions and the orofacial examination", "kicker": "Week 4 · Procedures", "week": "Week 4 (+ textbook Ch. 6, 9/21 lecture)", "summary": "CDC standard precautions, the tools you need vs may need for an orofacial exam, and how to interpret the twelve findings on her slide.", "sections": [{"h": "Standard precautions (slide 2)", "body": ["**Required across all settings.** CDC standard precautions apply to all health care settings. Most relevant for SLPs: **proper hand hygiene; PPE; respiratory hygiene; appropriate client placement; clean and disinfect the environment.**"], "callouts": [{"k": "source", "t": "The assigned OPE video: every oral peripheral exam involves mucous membranes, so standard precautions always apply regardless of the diagnosis (hand hygiene, gloves, cleaning tools between clients).", "ev": "video"}], "src": ["W4:slide 2", "OPE:2:45-3:41", "TB6: relevant section reviewed for this topic"]}, {"h": "Orofacial examination (slide 4)", "table": {"head": ["Purpose", "Clinician WILL need", "MAY need"], "rows": [["Identify or rule out structural or functional factors", "Disposable gloves; flashlight; tongue depressor", "Bite block; cotton gauze; applicator stick; mouth swab; stopwatch; mirror"]]}, "callouts": [{"k": "lecture", "t": "9/21: she classified the oral mechanism exam as an INFORMAL measure, because it is not standardized and has no psychometric foundation behind it.", "ev": "lecture"}, {"k": "trap", "t": "Stopwatch and mirror are 'may need' on her slide even though DDK timing and nasal-airflow checks use them.", "ev": "slide"}], "src": ["W4:slide 4", "L0921"]}, {"h": "Interpreting the orofacial exam (slide 5 + textbook meanings)", "table": {"head": ["Finding on her slide", "What the textbook says it may indicate"], "rows": [["Abnormal color of tongue, palate, pharynx", "Grayish: muscular paresis/paralysis. Bluish: excessive vascularity or bleeding. Whitish along the hard/soft palate border: submucosal cleft. Dark or translucent on the hard palate: fistula or cleft. Dark spots: possible oral cancer."], ["Abnormal height or width of palatal arch", "Wide/high: difficulty with palatal-lingual sounds; low/narrow with a large tongue: consonant distortions"], ["Asymmetry of face or palate", "Often neurological impairment or muscle weakness"], ["Deviation of tongue or uvula", "Tongue deviates TOWARD the WEAKER side on extension; uvula deviates TOWARD the STRONGER side on phonation"], ["Enlarged tonsils", "Often no effect on speech; sometimes affects health, resonance, hearing; forward tongue carriage"], ["Missing teeth", "May impair articulation; usually temporary"], ["Mouth breathing", "Possible restricted nasal passage; persistent + hyponasal → otolaryngologist referral; linked with anterior tongue rest posture"], ["Poor intraoral pressure", "Air from the lips: labial weakness. Air through the nose: velopharyngeal inadequacy (insufficiency = structural; incompetence = functional)"], ["Prominent rugae", "Narrow/low palate, large tongue relative to palate; associated with tongue thrust"], ["Short lingual frenulum", "May cause infant feeding problems; rarely an articulation disorder except in severe cases"], ["Weak, asymmetrical, absent gag reflex", "Possible velopharyngeal weakness/neurological impairment; some people with normal muscles have no gag"], ["Weakness of lips, tongue, jaw", "Common with neurological impairment (aphasia, dysarthria or both may be present)"]]}, "callouts": [{"k": "conflict", "t": "Tongue-tie emphasis differs between sources. The textbook says a short lingual frenulum is rarely associated with an articulation disorder except in severe cases; the OPE presenter stresses judging restriction by FUNCTION (elevation), not appearance. Both agree that appearance alone doesn't settle it.", "ev": "textbook"}], "src": ["W4:slide 5", "TB6: relevant section reviewed for this topic", "OPE:52:27-54:52"]}], "concepts": ["m12-precautions", "m12-tools", "m12-findings"]}, {"id": "m13", "number": 13, "title": "OPE video I: posture, movement, airway, rest", "kicker": "Week 4 · Assigned video", "week": "Week 4 Friday (discussed 9/21)", "summary": "Justine Sherman's oral peripheral exam, first half: why a thorough OPE matters, posture as the foundation, the four movement concepts, facial symmetry, airway and resonance, oral rest posture, jaw, cheeks and lips.", "sections": [{"h": "Why a thorough OPE matters", "body": ["Her Week 4 Friday slide assigned the video 'What SLPs Need to Know: How to Perform (And Interpret) a High-Quality Oral Peripheral Exam' (Justine Sherman, SLP) to discuss Monday; you discussed it on 9/21.", "The OPE looks at **structure, tone, symmetry, mobility, airway, sensory components, compensations and functional impact**. It helps identify structural and functional contributors to speech, feeding, resonance and airway issues, explain possible causes, individualize treatment, and know when and to whom to refer.", "**Teaching tip:** whenever therapy for speech, feeding or resonance isn't progressing as expected, **go back to your OPE first**.", "**Safety:** every OPE involves mucous membranes, so **standard precautions always apply** (hand hygiene, gloves, cleaning tools). **Tools:** a flashlight or headlamp (a poor light source leads to poor decisions); a tongue depressor is for **stabilization, not force**; a mirror helps check nasal airflow. If you can't see it clearly, don't guess."], "callouts": [{"k": "lecture", "t": "9/21 class discussion picked up on posture affecting the oral pathway and airway, and on tongue-thrust/orofacial myofunctional patterns: braces can relapse if a lingual fronting (thrust) pattern isn't corrected, because we swallow thousands of times a day.", "ev": "lecture"}], "src": ["W4OPE:slides 1-2", "OPE:0:07-4:05", "L0921"]}, {"h": "Posture and the four movement concepts", "visual": "four", "body": ["Posture is **the foundation** of the orofacial mechanism. Observe it **at rest, not on command**, starting in the lobby: head stacked over shoulders or forward? shoulders rounded? trunk supported or collapsed? Upright posture supports breath support, jaw stability, oral rest posture and motor control. Slouched posture → reduced respiratory support, jaw instability, **low and forward tongue**, more compensation."], "table": {"head": ["Concept", "Definition (video)", "What poor control looks like"], "rows": [["Stability", "Ability to maintain a controlled, supported position (jaw is a MOBILE STABILIZER for tongue and lips)", "Jaw sliding, biting or excessive movement to compensate"], ["Mobility", "Ability to move efficiently through range without restriction", "Reduced range of motion even when structures are anatomically normal; neck/shoulder tension"], ["Dissociation", "Ability to move one part independently of another", "Head moves during tongue tasks; jaw lifts during lip tasks; excessive mentalis activation"], ["Grading", "Control of speed, force and range of movement", "Overshooting, undershooting, 'all-or-nothing' movement"]]}, "callouts": [{"k": "source", "t": "Forward head posture is 'a key clinical clue': think airway and breathing (mouth breathing, low tongue rest, narrowed oral/pharyngeal space). Referrals when posture affects function: OT (core stability, sensory-motor integration), PT (alignment, movement efficiency), ENT/medical (airway).", "ev": "video"}], "src": ["OPE:4:12-12:21"]}, {"h": "Facial symmetry: rest vs movement", "body": ["Assess the face **completely at rest** first (baseline tone and structure), then during intentional movement: smile, pucker, retract, alternate pucker/retract, tongue tasks with the face relaxed.", "**Asymmetry at rest that IMPROVES with movement** → often a structural difference or habitual resting pattern; motor control likely intact. **Asymmetry that APPEARS or WORSENS with movement** → concern for neuromuscular weakness or cranial nerve involvement, **especially cranial nerve VII**.", "**Asymmetry is not inherently pathological; the pattern matters.** Document the pattern and conditions: e.g., 'mild right-sided lip weakness observed during retraction tasks, increasing with sustained movement; symmetry improved at rest.'"], "src": ["OPE:11:19-17:13"]}, {"h": "Airway and resonance", "body": ["Observe breathing at rest (mouth open/closed; nasal, oral or mixed; effort such as nasal flaring). Nasal breathing at rest is typical; **mouth breathing at rest often suggests obstruction or chronic congestion**.", "**Mirror, task 1:** under the nostrils during normal breathing: presence and symmetry of **fogging**; consistently reduced or absent fogging on one side suggests decreased airflow (turbinate hypertrophy, septal deviation, chronic inflammation). **Mirror, task 2:** during pressure-heavy NON-nasal sounds (/s/, /z/, p, b, t, d; 'big puppy'): nasal air escape is clinically meaningful because pressure sounds need oral airflow and velopharyngeal closure."], "table": {"head": ["Finding", "Meaning", "Points toward"], "rows": [["Hyponasality", "Too little nasal resonance", "Obstruction (e.g., enlarged tonsils/adenoids when no congestion)"], ["Hypernasality", "Excessive nasal resonance", "Velopharyngeal dysfunction"], ["Nasal emission", "Air escaping through the nose on oral pressure sounds", "Possible VPI"], ["Cul-de-sac", "A mix; sounds muffled", "(briefly described)"], ["Intermittent congestion", "", "Allergies"], ["Consistent uni/bilateral obstruction", "", "Structural issue: turbinates, tonsils, adenoids"]]}, "callouts": [{"k": "source", "t": "Referrals: ENT, allergist, sleep medicine (sleep study for suspected apnea). As an orofacial myologist she sends a consistently hyponasal, obstructed client to ENT or an allergist BEFORE starting therapy, because proper rest posture (lips closed, nasal breathing) isn't possible otherwise.", "ev": "video"}], "src": ["OPE:20:31-28:17"]}, {"h": "Oral rest posture", "body": ["Rest posture shows how the system is organized most of the day. **Observe before any instruction**: once you cue 'close your mouth' or 'tongue up', you lose information about natural rest. Observe over time (lobby, transitions, while listening).", "Typical rest: **mouth closed, nasal breathing, tongue elevated in a gentle 'suction' on the palate with the tip on the 'spot' just behind the upper front teeth**, lips closed without strain, mentalis relaxed, jaw relaxed but supported, quiet efficient breathing.", "Atypical: open-mouth posture (nasal obstruction, low tone/postural support, or a long-standing habit such as pacifier or thumb sucking) → mouth breathing, dry mouth, more illness, non-restorative sleep; low forward tongue → less palatal stimulation, palate may narrow, airway compromised.", "Rest posture happens **20+ hours a day**, far more than a 30-minute session; therapy can't override inefficient rest posture if structural or airway barriers are present. **An atypical rest posture alone does not equal pathology**: can they achieve it with a cue, maintain it, and are there symptoms (snoring, mouth breathing, fatigue)?"], "src": ["OPE:28:17-33:38"]}, {"h": "Jaw, cheeks and lips", "table": {"head": ["Structure", "Tasks / observations", "Key interpretations"], "rows": [["Jaw", "Rest; open/close slowly; open wide and hold; side to side; then conversation, DDK, reading/counting", "Oral placement therapy triangle: jaw, lips, tongue, and JAW ALWAYS COMES FIRST. Deviation toward one side often reflects weakness or restriction on that side. Improves with cueing/postural support → habitual/compensatory; persists → true weakness. Pain, clicking, restricted range → structural, refer. Stable at first but deteriorates → reduced endurance."], ["Cheeks (buccal)", "Fullness vs flattening; puff cheeks; hold air in one cheek; maintain against gentle external pressure; speech; feeding", "Weak buccal tone → food pocketing in the lateral sulci, inefficient chewing/clearing, distorted pressure consonants. Check buccal frenula. Refer ENT/dentistry (tethered tissue), OT, feeding specialist."], ["Lips", "Rest seal and labial frenula; pucker, smile, alternate; 'oo'/'ee'; straw, cup, spoon", "Hyperactive MENTALIS (chin muscle) pushing the lower lip up = compensation for poor lip closure by the ORBICULARIS ORIS. Flaccid lips → drooling, reduced pressure; hypertonic lips limit movement; asymmetry → possible neuromotor involvement."]]}, "callouts": [{"k": "source", "t": "Q&A: asked whether large jaw movement is typical under age five, the presenter said she did not know the exact answer, but assumed excessive jaw sliding should not be seen even at 5. Do not treat that as an age norm.", "ev": "video"}], "src": ["OPE:33:38-52:27"]}], "concepts": ["m13-why", "m13-four", "m13-posture", "m13-airway", "m13-rest", "m13-jawlips"]}, {"id": "m14", "number": 14, "title": "OPE video II: tongue, teeth, palate, DDK, documentation", "kicker": "Week 4 · Assigned video", "week": "Week 4 Friday (discussed 9/21)", "summary": "Tongue assessment and the TRMR, occlusion classes and bite terms, hard palate and rugae, soft palate and tonsils, the submucous cleft triad, DDK interpretation, and turning observations into clinical interpretations.", "sections": [{"h": "Tongue and the TRMR", "visual": "oral", "body": ["At rest: size, texture, **scalloping** on the lateral borders (from a narrow palate with the tongue pushing against the teeth, or from jaw clenching), and resting posture (tip on the alveolar ridge, or low and forward?). Mobility: up to the alveolar ridge and down; lateralize; reach back molars; retract; cup; suction to the roof of the mouth; rapid alternating movements. Look for symmetry, range, speed, grading, and **tongue-jaw dissociation**.", "**Tongue range of motion ratio (TRMR)** (designed by 'Dr. Zagi' (as captioned) of the Breathe Institute) measures FUNCTION, not frenum appearance: measure maximal interincisal opening with the tongue down, then the opening with the tongue tip on 'the spot'; **(tongue-up opening ÷ maximum opening) × 100**."], "table": {"head": ["TRMR", "Presenter's category"], "rows": [[">80%", "Typical tongue mobility"], ["50-80%", "Mild restriction"], ["<50%", "Moderate to severe restriction"]]}, "callouts": [{"k": "numbers", "t": "Example: 24 mm tongue-up ÷ 40 mm max × 100 = 60% → mild. 18 ÷ 40 × 100 = 45% → moderate-severe. Exactly 80% or 50% is not assigned by the presenter's wording (>80, 50-80, <50 puts 80 and 50 in 'mild').", "ev": "video"}, {"k": "source", "t": "Posterior tongue tie: the person CAN stick the tongue out but CANNOT elevate it, so it is often missed ('they can stick their tongue out, they're fine'). Without elevation the tongue can't spread the palate → narrow, vaulted palate and poor rest posture.", "ev": "video"}], "src": ["OPE:52:27-54:52"]}, {"h": "Dentition and occlusion", "visual": "occlusion", "body": ["Reference point: the **upper and lower FIRST MOLARS**. **Class I** (normal): the cusp of the upper first molar fits into the groove of the lower first molar. **Class II** (often called an 'overbite', retrognathic): the upper first molar sits FORWARD relative to the lower; the lower jaw appears retruded, the upper teeth protruded. **Class III**: the upper first molar sits BEHIND the lower; the lower jaw appears prominent/protruded."], "table": {"head": ["Term", "Meaning in the video"], "rows": [["Open bite", "Top and bottom teeth don't come together (often front or lateral; tongue thrust, thumb sucking, pacifier)"], ["Overjet", "HORIZONTAL distance between upper and lower front teeth is too great ('bucky beaver teeth'; what people often call an overbite)"], ["Overbite", "Top teeth come too far down over the bottom teeth: VERTICAL overlap"], ["Crossbite", "Part of the upper teeth sits inside the lower teeth; unilateral, bilateral or anterior"]]}, "src": ["OPE:54:40-58:07"]}, {"h": "Hard palate, rugae, soft palate, tonsils", "body": ["Hard palate: shape and height (narrow, wide, shallow, vaulted); width relative to the tongue; integrity (clefts, fistulas, lesions); symmetry; rugae. Functional check: can the tongue reach the alveolar ridge/palate, suction, manipulate a bolus; /t, d, n, l/. A narrow or high-arched palate can restrict tongue movement and increase anterior tongue thrust. Pictures shown: **torus palatinus** (bony protuberance: 'we are not worried about that'), a narrow vaulted palate ('chicken or egg': thumb sucking/pacifier vs tongue tie), defined rugae, a fistula.", "**Rugae:** children show defined rugae; in adults with proper tongue rest posture the area behind the upper teeth should feel smooth. Defined rugae in an adult suggest the tongue isn't elevating there.", "Soft palate (velum): resting height and symmetry; scarring; sustained vowel 'ah'; elevation to the posterior pharyngeal wall. Reduced or asymmetrical elevation → hypernasality, nasal emission, weak pressure for plosives, compromised swallowing. Adequate isolated elevation but inconsistency in connected speech → coordination or fatigue.", "Tonsils should sit just within the tonsil pillars, not 'kissing'. Use a **grading system** so you can compare later (e.g., 'used to be a 2, now a 4'). If you cannot see the soft palate at all, suspect airway obstruction."], "callouts": [{"k": "textbook", "t": "Textbook disagrees in emphasis about rugae: it links prominent rugae to a narrow/low palate, a large tongue, and tongue thrust. Both sources connect rugae to tongue-palate relationships.", "ev": "textbook"}], "src": ["OPE:58:07-1:07:37", "TB6: relevant section reviewed for this topic"]}, {"h": "Submucous cleft palate", "body": ["Often missed because **the mucosa is intact**. The **classic triad**: (1) **bifid (split) uvula**; (2) **zona pellucida**, a translucent midline zone in the soft palate; (3) a **palpable notch or groove at the posterior hard palate**. These indicate possible VPI: hypernasality, nasal emission, compensatory articulation (glottal stops, pharyngeal substitutions).", "**A bifid uvula alone is not diagnostic**; two or more markers increase suspicion, and consistent hypernasality or nasal emission supports it. **Therapy alone cannot correct anatomical deficits**; refer to craniofacial/ENT (and feeding/nutrition if needed)."], "callouts": [{"k": "textbook", "t": "Textbook color cue: a whitish color along the border of the hard and soft palate is a symptom of a submucosal cleft.", "ev": "textbook"}], "src": ["OPE:1:07:37-1:10:23", "TB6: relevant section reviewed for this topic"]}, {"h": "DDK interpretation", "visual": "ddk", "body": ["DDK gives insight into motor planning, coordination and neuromuscular integrity, **not just speed**: observe accuracy, rhythm, consistency and coordination in addition to rate.", "**AMR** (alternating motion rate): repeat one syllable quickly on one breath (puh-puh, tuh-tuh, kuh-kuh): bilabial (p), alveolar (t) and posterior (k) control. **SMR** (sequential motion rate): repeat puh-tuh-kuh; children can say 'buttercup'."], "table": {"head": ["Pattern", "Presenter's interpretation"], "rows": [["Slow, imprecise AMRs AND SMRs", "Possible dysarthria or weakness"], ["Adequate AMRs but poor SMRs", "Motor planning / sequencing (programming) deficit; may be childhood apraxia of speech"], ["Irregular rhythm or breakdown with fatigue", "Neuromuscular involvement"], ["Equal stress or segmentation", "Impaired temporal coordination"]]}, "callouts": [{"k": "source", "t": "Referrals: neurology (new, progressive or asymmetrical deficits); OT/PT (global motor coordination or tone); further motor speech evaluation to differentiate dysarthria from apraxia.", "ev": "video"}], "src": ["OPE:1:10:23-1:15:07"]}, {"h": "Form and function: documentation that interprets", "body": ["**Structure is the chicken (anatomy, alignment, integrity); function is the egg (movement, coordination, pressure, timing).** The key question is not 'what do I see?' but **'how does what I see impact what the client can do?'** A high narrow palate doesn't matter unless it restricts tongue movement, which then affects resonance or swallowing.", "Weak: 'high-arched palate.' Strong: 'high-arched narrow palate limiting tongue-palate contact, contributing to distorted alveolar sounds and reduced bolus control.' That is the difference between an **observation** and a **clinical interpretation**; other professionals need us to explain impact, not name anatomy."], "src": ["OPE:1:15:07-1:17:55"]}], "concepts": ["m14-tongue", "m14-teeth", "m14-palate", "m14-smc", "m14-ddk", "m14-document", "m14-diagram"]}, {"id": "m15", "number": 15, "title": "DDK, sampling, rate, intelligibility, charting", "kicker": "Week 4 · Procedures", "week": "Week 4 (+ textbook Ch. 6)", "summary": "How to administer DDK (Method 2), what a speech-language sample is for and how long it should be, eliciting narratives and reading passages, calculating speech rate, what reduces intelligibility, syllable-by-syllable phrases and charting.", "sections": [{"h": "DDK administration (slides 6-7)", "body": ["**AMR** = repetition of a single syllable; **SMR** = repetition of varying syllables. Measured two ways: **Method 1** counts syllables produced within a number of seconds; **Method 2** measures the seconds it takes to produce a number of syllables, and **Method 2 is more common**.", "**Method 2 steps:** instruct the client to repeat the target syllable; model the sequence; say **go** and start the stopwatch; say **stop** and stop the stopwatch **after 20 reps**; redo if the client stops or slows down; after assessing syllables independently, evaluate **10 reps of 'puh-tuh-kuh'**; record findings on the worksheet."], "callouts": [{"k": "numbers", "t": "20 repetitions per single syllable; 10 repetitions of puh-tuh-kuh. Textbook: Form 6-2 is based on Fletcher (1972) with norms for ages 6-13; young children can say 'pattycake' or 'buttercup'; redo if they stop or intentionally slow down (not due to fatigue).", "ev": "slide"}], "src": ["W4:slides 6-7", "TB6: relevant section reviewed for this topic"]}, {"h": "Speech-language sampling (slides 8-9)", "body": ["Time-consuming but **worth the time and effort**. Purposes on her slide: identifying sound errors; determining eligibility; evaluating rate; assessing fluency; determining MLU; assessing imitation and comprehension; semantic, syntactic, morphological skills; narrative skills, vocal quality, resonance; pragmatic skills.", "Length: **long enough to obtain a representative sample: 50-100 minimum utterances.** Strategies: establish a positive relationship; minimize interruptions; **be willing to wait** for the client to talk; preselect materials and topics; vary subject matter; seek multiple environments; alter contexts; use a good-quality recorder; ask others to provide recorded samples; ask questions that elicit lengthier responses; make natural contributions; consider age and culture."], "callouts": [{"k": "conflict", "t": "Sample-length numbers differ by source, so key to HER slide: Week 4 slide 9 = 50-100 minimum utterances. Textbook Ch. 6 = minimum 50-100 distinct utterances, continue to 200+ if possible; textbook Ch. 1 = 50-200. Her COMD 4382 record taught '100 complete and intelligible utterances' (historical, older course). For this course, 50-100 is the current slide value.", "ev": "slide"}], "src": ["W4:slides 8-9", "TB6: relevant section reviewed for this topic", "TB1: relevant section reviewed for this topic", "CODEX:section 9"]}, {"h": "Conversation starters, pictures, narratives, reading passages (slides 10-11)", "bullets": ["Many clinicians **provide a model** (share a personal experience first). Stimulus questions: 'Do you have a pet? Tell me about it.' 'Have you ever been in an airport?' 'Ever gotten lost at the store?' 'What is your favorite food? How do you make it?'", "Pictures are often useful; use pictures that illustrate **a variety of activities** (textbook: pictures with little action or that elicit naming only are of little use).", "**Narratives**: the child must use rules of **cognitive organization and language sequencing**. Sources: retelling familiar stories; retelling a movie plot; wordless storybooks; wordless videos; sequencing picture cards.", "**Reading passages** allow observation of **articulation, voice, fluency, reading abilities**; compare oral reading with single-word/short-phrase utterances and conversational samples (Appendix 6-B). Textbook: the client cannot avoid challenging sounds or words in fixed text."], "src": ["W4:slides 10-11", "TB6: relevant section reviewed for this topic"]}, {"h": "Rate of speech (slide 12)", "body": ["Average rates vary. **The importance is NOT to compare with preestablished norms; it allows the clinician to evaluate the effect on the client's communicative abilities.**", "Record connected speech (**minimum of 1-2 minutes**). Four steps: **time the sample in seconds; count the words; divide words by seconds; multiply by 60 → wpm.** Textbook example: 60 words in 75 seconds → 0.8 × 60 = 48 wpm."], "src": ["W4:slide 12", "TB6: relevant section reviewed for this topic"]}, {"h": "Intelligibility (slide 13)", "body": ["The sample must be **adequate and representative**; audio or video record it. Factors that can reduce intelligibility: number of phonemic errors; types of phonemic errors; vowel errors; fast rate; atypical prosody; length and complexity of utterances; insufficient vocal intensity; disfluencies; lack of paralinguistic cues; testing environment; client's lack of familiarity or fatigue; **clinician's ability to understand less intelligible speech or familiarity with the client**."], "callouts": [{"k": "textbook", "t": "Textbook: omissions and additions generally reduce intelligibility more than substitutions or distortions; report intelligibility as approximate; compare word-by-word and utterance-by-utterance.", "ev": "textbook"}], "src": ["W4:slide 13", "TB6: relevant section reviewed for this topic"]}, {"h": "Syllable-by-syllable phrases and charting (slides 14-15)", "body": ["Verbal phrases as stimuli are useful for assessing many disorders. Clinical questions: can the client maintain appropriate **nasal resonance**? what **speech rate** is optimal? are there **syllable lengths at which articulation decreases**? Articulation, rate, prosody, inflection and intonation can be sampled with these lists.", "**Charting behaviors**: objectively scoring client responses; any behavior of interest can be tracked. Ways: note each time a behavior is exhibited; note instances of correct AND incorrect behaviors; note subtype or variance of a behavior. Forms 6-5 and 6-6."], "callouts": [{"k": "textbook", "t": "Textbook: Form 6-5 charts up to 200 responses; Form 6-6 up to 100. Example: 7 of 10 correct = 70%.", "ev": "textbook"}], "src": ["W4:slides 14-15", "TB6: relevant section reviewed for this topic"]}], "concepts": ["m15-ddkadmin", "m15-sample", "m15-narrative", "m15-rate", "m15-intel", "m15-phrases"]}, {"id": "m16", "number": 16, "title": "Observation, informal and dynamic assessment", "kicker": "Week 5 · Methods", "week": "Week 5 (+ 9/21 lecture)", "summary": "Three ways to gather information beyond standardized tests, and the question each one answers.", "sections": [{"h": "Three methods, three questions (slides 2-3, 8)", "visual": "three", "table": {"head": ["Approach", "Description (slide 3)", "The question (slide 8)", "Her narrative example"], "rows": [["Clinical observation", "Watching and listening to a client during natural or structured activities", "'What do I see/hear the client doing?'", "Watch the child during play: short utterances, rarely provides information about what happened"], ["Informal assessment", "Non-standardized tasks or measures designed by the clinician to examine a particular skill", "'What can the client do on this task?'", "Show a picture sequence and ask for the story; record grammar, vocabulary, story structure, sequencing"], ["Dynamic assessment", "A process of assessing AND teaching to see how the client responds to support", "'What happens when I teach/support the client, and can they use what they learned?'", "Independent story → teach a framework (character → setting → problem → action → outcome) with modeling and cues → retell a NEW story and see if the strategy transfers"]]}, "src": ["W5:slides 2-3, 8"]}, {"h": "Clinical observation (slide 4)", "body": ["Where: during conversation; during play; in the classroom; **during a standardized assessment**; while interacting with family members; during structured activities.", "What: how the person **initiates** communication; **eye contact and joint attention**; **turn-taking**; **use of gestures**; **speech intelligibility**; **voice quality**; **fluency**; how they **respond to questions**; whether they **need repetition or cues**; **communication breakdowns and how they repair them**."], "callouts": [{"k": "lecture", "t": "9/21: observation starts as the client walks in (posture, breathing, how the parent responds). She noted children under 3 are much more likely not to perform on demand.", "ev": "lecture"}], "src": ["W5:slide 4", "L0921"]}, {"h": "Dynamic assessment (slides 5-6)", "body": ["Goes a step further than 'Can the client do this?' It typically uses **test-teach-retest**: **Test** (e.g., produce a new sound without assistance) → **Teach** (instruction, modeling, cues, feedback, practice) → **Retest** (more accurate, particularly **with reduced support**?). The clinician is interested in **responsiveness to intervention**.", "Useful for understanding: **learning potential**; **what types of cues are effective**; **how much support the client needs**; **whether difficulties relate to lack of experience versus difficulty learning the skill**; how the client responds to instruction."], "callouts": [{"k": "textbook", "t": "Textbook: the teaching phase is a mediated learning experience (MLE); DA is a primary method for differentiating disorder from difference in multicultural clients. Her Week 3 slide: no improvement → more likely language impairment.", "ev": "textbook"}, {"k": "gonsoulin", "t": "COMD 4382 record: 'LSA is true EXCEPT: it is a dynamic assessment.' A sample is informal/formative, not dynamic, because there is no teaching phase. Historical item.", "ev": "historical"}], "src": ["W5:slides 5-6", "TB1: relevant section reviewed for this topic", "W3B:slide 11", "CODEX:section 4"]}, {"h": "Informal assessment (slides 7, 10)", "body": ["A **non-standardized** activity to gather information about a specific skill; it doesn't necessarily have standardized procedures, norms or scores. **Unlike simply observing, the clinician usually sets up a task and collects information.** Language examples: name pictures; describe a picture; follow increasingly complex directions; retell a short story; answer questions about a conversation or passage. Speech sound example: a clinician-made word list with particular sounds, recording which are correct.", "Slide 10: for clients who **do not match the normative profiles** of available standardized tests, **the entire assessment can be based on informal measures**. **Reliability and validity of the findings depend on the clinician's level of expertise and how representative the language data are.**"], "src": ["W5:slides 7, 10"]}, {"h": "Cause, intention, and access", "body": ["The supplied cause-and-effect activity asks whether an intentional action produces a desired outcome, and whether the child repeats the action to obtain that outcome. Describe the action, result, repetition and communicative purpose. An accidental activation alone is weaker evidence of intentional cause-and-effect use.", "Check whether sensory or motor demands prevent access to the toy. A child who cannot reach or see the mechanism may understand the outcome despite unsuccessful activation. Adapt access and gather another observation before interpreting understanding."], "src": ["Supplied cause-and-effect activity notes", "September 23 lecture"]}, {"h": "Use the supplied play checklist correctly", "body": ["The Heidemann and Hewitt (2010) play checklist says to check the highest-level skills you consistently observe. One advanced action on one occasion does not establish consistent performance. Children need not follow every listed step or the same developmental order.", "Look across pretending with objects, role play, verbalizations about a scenario, communication during play, persistence, interactions, entering a group, problem solving, turn taking and support for peers. Pretending can use a real object, a substitute, or an imaginary object; role play includes coordinated roles and declaring a role verbally. These are observations in the checklist’s context, not universal diagnostic cutoffs."], "src": ["Supplied Play Checklist, p.1 (Heidemann & Hewitt, 2010)"]}], "concepts": ["m16-three", "m16-observe", "m16-dynamic", "m16-informal"]}, {"id": "m17", "number": 17, "title": "Language sample analysis and narratives", "kicker": "Week 5 · Analysis", "week": "Week 5 · including September 23 lecture", "summary": "What to note in a language sample, semantic analysis, narrative comprehension (literal vs inferential), and the three narrative levels.", "sections": [{"h": "Language sample analysis (slide 11)", "bullets": ["Collect a representative sample based on real conversation; collect multiple samples; vary contexts and activities; ask others to interact with the child; record for later analysis.", "Observe: **form** of language; understanding **semantic intent**; language **use**; **rate** of speaking; **sequencing**.", "Computerized tools help analyze samples efficiently: **CLAN** and **SALT**."], "callouts": [], "src": ["W5:slide 11"]}, {"h": "Semantic skills (slide 12)", "bullets": ["Number of different words", "Unusual use of words", "Incorrect word substitutions", "Overgeneralizations or undergeneralizations", "Frequent use of empty words", "Word-finding problems", "Types of words", "Excessive use of pronouns", "Frequent use of routinized expressions"], "src": ["W5:slide 12"], "callouts": []}, {"h": "Narratives (slides 13-16)", "body": ["The ability to tell or retell a story reveals a lot about language; narrative assessment can be part of spoken and/or written language assessment.", "**First determine whether the client understands the story.** Can they identify characters, setting, the problem or initiating event, important actions/events, the outcome/resolution; answer **literal** questions; answer **inferential** questions; identify the main idea; explain why events happened; predict what might happen next; retell the story? Example: after a story about a boy who loses his dog, ask 'Why did the boy go looking for his dog?'"], "visual": "levels", "table": {"head": ["Level", "What you examine", "Examples"], "rows": [["Macrostructure", "Organization/content of the story", "Setting, problem, goal, attempts, consequence, resolution"], ["Microstructure", "Language inside the story", "Grammar, vocabulary, syntax, cohesion"], ["Higher-level language", "Meaning beyond individual sentences", "Inferences, motivations, causal relationships, perspective-taking"]]}, "callouts": [{"k": "numbers", "t": "Slide 16 macrostructure checklist: character, setting, initiating event/problem, goal, attempts, consequences, resolution, ending.", "ev": "slide"}], "src": ["W5:slides 13-16"]}, {"h": "Keep developmental checklists in context", "body": ["Use the supplied Speech and Language Developmental Checklist, second edition, to organize caregiver reports and observed skills. Its age examples belong to that edition and checklist. Do not splice its speech-rate or intelligibility ages into unrelated sound-acquisition tables, or treat one unchecked milestone as a diagnosis. Triangulate history, direct samples and relevant current-course evidence."], "src": ["Supplied Speech and Language Developmental Checklist, second edition, pp.1–5"]}], "concepts": ["m17-lsa", "m17-semantic", "m17-narcomp", "m17-levels"]}, {"id": "m18", "number": 18, "title": "Numbers workshop: her conventions under pressure", "kicker": "Integrated · Procedures", "week": "Weeks 2-4", "summary": "Every computed and classified number in the course, practiced at the boundaries: ages, score transfers, bell-curve bands, percentiles, rate, TRMR.", "sections": [{"h": "How this workshop uses her conventions", "body": ["All band labels come from her Week 2 bell-curve slide; all scales from her slide 17 table. Where the course sources disagree (CA borrow days; −1.5 SD 'significantly below' in the textbook; exact 70/130), the item states the convention or avoids the ambiguous value. Use the Tools tab to check any number against the same functions the answer keys use."], "callouts": [{"k": "numbers", "t": "Transfer rule: z = (score − mean) ÷ SD, then new score = new mean + z × new SD. Standard 100/15; scaled 10/3; z 0/1; stanine 5/2.", "ev": "slide"}], "src": ["W2:slides 17-18"]}], "concepts": ["m18-ca", "m18-transfer", "m18-boundary", "m18-mixed"]}, {"id": "m20", "number": 20, "title": "Comprehensive SSD assessment & GFTA recording", "kicker": "Week 6", "week": "Week 6", "summary": "Combine speech contexts, history, oral/hearing evidence, stimulability and impact; practice accurate error recording.", "sections": [{"h": "The comprehensive assessment", "body": ["Screening quickly identifies a possible concern; it does not establish a diagnosis. An SSD evaluation combines case history (including ear infections, PE tubes and cleft history), oral structure/function, hearing screening or recent audiological findings, perception, single-word productions and connected speech."], "bullets": ["Analyze error number, type, form, position and consistency.", "Hearing screening can include otoscopy and immittance as well as audiometric evidence; review the appropriate procedures and current findings.", "Classify substitutions, omissions, distortions, additions and syllable deletions. Note whether errors occur initially, medially or finally (for example, the target /s/ in sun, messy and bus).", "Compare error patterns with rate and intelligibility.", "Check language, linguistic systems, social and academic impact."], "src": ["W6:slides 2–11,16"]}, {"h": "Stimulability and norms", "body": ["Stimulability is the ability to produce an erred phoneme correctly with support. It supplies prognostic information; it is not a diagnosis by itself.", "Phoneme acquisition, conversational acquisition, cluster development and frequency of occurrence describe different phenomena. Use the table for the question and linguistic context. Do not rely solely on developmental norms."], "src": ["W6:slides 13–16", "Textbook Ch.7: Tables 7–5 through 7–9, pp.216–218"]}, {"h": "Production versus phonological processing", "table": {"head": ["Question", "Construct"], "rows": [["How does the child say the word?", "Speech sound production"], ["Can the child think about, remember or manipulate speech sounds?", "Phonological processing"]]}, "src": ["W6:slide 21"]}, {"h": "GFTA error recording", "table": {"head": ["Response", "Record"], "rows": [["Substitution", "IPA symbol for the actual substituted sound"], ["Omission/deletion", "Dash in the appropriate column"], ["Distortion", "Diacritic or explanatory note"], ["No response", "NR"]]}, "body": ["Follow the applicable GFTA manual and standardized prompts. Record in real time. The available GFTA-2 video is a historical procedure example; it does not replace the GFTA-3 materials used in class. KLPA-3 can contribute phonological analysis alongside the articulation evidence."], "src": ["W6:slides 22–25", "September 30 lecture"]}, {"h": "Why the oral task?", "table": {"head": ["Task", "Purpose"], "rows": [["Pucker / smile", "Lip range and symmetry"], ["Puff cheeks and hold", "Lip closure/strength, pressure and possible nasal emission"], ["Tongue excursion and resistance", "Range, symmetry, strength and dissociation"], ["Sustain /ɑ/", "Observe velar movement, uvula and nasality"]]}, "body": ["The Week 6 exercise specifically asks you to model tasks and define unfamiliar words. Match each command to the evidence it yields."], "src": ["W6:slide 26", "Form 6–1: textbook pp.169–172"]}], "concepts": ["w6-plan", "w6-screen", "w6-context", "w6-intelligibility", "w6-stim", "w6-norms", "w6-processing", "w6-record", "w6-task"]}];
